INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES (7746,3,1,'အလုံးနှစ်ဆယ်မြောက်မွန်ဗျည်း။',NULL)
,(7747,3,1,'တောင်း။','“ခအဳခိုဟ်၊ ရိခိုဟ်၊ နခိုဟ်၊ ကၞာဲခိုဟ် အဲသၟိက်ဂွံရ” ဍိက်ဗြဴဂး။ (ဇ—၂၈၉။အစွောံ။) = “ဆုံကောင်း၊ ကျည်ပွေ့ကောင်း၊ တောင်းကောင်း၊ ဆန်ကောကောင်းတို့ကို ငါလိုချင်၏။”')
,(7748,3,1,'ခြင်းတောင်းကြီး။',NULL)
,(7749,3,1,'ကွမ်းသီး၊ ကွမ်းထည့်သောတောင်း။ ကွမ်းအစ်။',NULL)
,(7750,3,1,'တင်းတောင်း။',NULL)
,(7751,3,6,'ဖြင့်။ အားဖြင့်။—ခြင်းဖြင့်။—ခြင်းအားဖြင့်။ (နာမ်ဖြင့်သော်၄င်း ကြိယာဖြင့်သော်၄င်းတွဲစပ်သုံးနိုင်သည်။)','စပုၚ်နတဲ၊ စပုၚ်နကဵုတဲ = လက်ဖြင့် ထမင်းစားသည်။ || “လၟုဟ်ဝွံ အဲဂွံမိၚ်နကတောဝ်ရ။” (ဇ—၃၅၉။ အစွောံ။) = “ယခုငါသည် နားဖြင့်တပ်အပ် ကြားရလေပြီ။” || “နအဲမပၟဝ်ဒၟံၚ်ဓဝ်မေတ္တာကီု ကရုဏာကီုဂှ် စုတိတုဲ အဲဂွံအာစိုပ်ဍုၚ်သွဝ်ဍုၚ်ဗြီုရ။” (ဇ—၇၆။ အစွောံ။) = “ငါသည် မေတ္တာတရားကို၄င်း ကရုဏာတရားကို၄င်း ပွားများနေခြင်းအားဖြင့် စုတေသည်ရှိသော် နတ်ပြည်ဗြဟ္မာပြည်သို့ လားရောက်ရလတ္တံ့။” || “နမဟီုဂၠိုၚ်ၚ်ကဵုဝါ ဂၞကျာ်အာတ်လွဵုဂှ်တုဲ သၟိၚ်မဒးကဵုလွဵု—။” (ဇ—၁၂ဝ။ အစွောံ။) = “အဖန်တလဲလဲပြောခြင်းအားဖြင့် မိဖုရားသည် ထိုဆုကိုတောင်းသဖြင့် မင်းသည် ထိုဆုကိုပေးလိုက်ရ၏။” || “နမဗၞုဟ်ဂုန်ရတ်ပိလေဝ် ဂွံပၠေၚ်ကၠေံပရိုက်ဥပ္ပဒြဴကီု။” (ဇ—၂ဝ၃။ အစွောံ။) = “ရတနာသုံးပါး၏ဂုဏ်တော်ကို အောက်မေ့ဆင်ခြင်ခြင်းဖြင့်လည်း ဘေးဥပဒ်ကို ကျိန်းကျေပျောက်ပြယ်စေနိုင်၏။”')
,(7752,3,5,'ချမ်းသာစွာဖြင့်။','“မၞိဟ်ဂမၠိုၚ်ဂှ် ဗၠးဘဲဂစိုတ်တုဲ နတသိုက်ဟေၚ်သ္ဍးအာရ။” (ဇ—၄ဝ၅။ အစွောံ။) = “လူများသည် သေဘေးမှလွတ်၍ ချမ်းသာစွာဖြင့် ဖဲခွါသွားကြကုန်၏။”')
,(7753,3,5,'မျက်မြင်အားဖြင့်။ ပစ္စက္ခအားဖြင့်။ မျက်မြင်ကိုယ်တွေ့။','“ဍေံကၠတ်ဒြပ်ဗှ်ေ အဲဂွံညာတ်နမတ်ရ။” = “နင့်ဥစ္စာကို သူခိုးတာ ငါမျက်မြင်တွေ့လိုက်တယ်။” || “(ဒုဟ်အမာတ်ဂှ်) သၟိၚ်ရံၚ်စံၜတ်တုဲ သၟိၚ်မဂွံညာတ်နမတ်တုဲ သၟိၚ်ဗက်ထောံကၠေံနူရးရ။” (ဇ—၃ဝ၃။ အစွောံ။) =“မင်းသည် ထိုအမတ်၏အပြစ်ကို စုံစမ်းသည်ရှိသော် မျက်မြင်အားဖြင့်မြင်၍ ထိုအမတ်ကို တိုင်းပြည်မှ နှင်ထုတ်လိုက်၏။”')
,(7754,3,5,'မျက်မြင်ထင်ရှားစွာ။ မျက်မြင်ဒိဋ္ဌ။ မျက်စိဖြင့်တပ်အပ်။','“သၟာသၞာ်ဂှ် မဂွံၚိတ် (သၞာ်) ဒေါဝ်ပေဲါဂတမတ်ညးဂမၠိုၚ် ဂွံညာတ်တဴနမတ်ဇၚ်ဇၚ်ဂှ် ပွဍေံဂှ် သ္ဇိုၚ်လောန်ဗၞတ်ရောၚ်သွံအမာတ်” သၟိၚ်ဂး။ (ဇ—၄ဝ၁။ အစွောံ။) = “အိုအမတ်၊ သန်လျက်သမားသည် ပွဲလယ်လူသူရှေ့မှောက်­ သန်လျက်ကိုမျိုခြင်းကို မျက်စိဖြင့်တပ်အပ်မြင်ရသည်မှာ သူပြုသောအမှုသည် အလွန်ခဲယဉ်းစွတကား။” || “မဂွံညာတ်သေနကတြုံတၠပညာ နမတ်ဇၚ်ဇၚ်ဂှ် ပြဲလောန်သန်ရအဴ။” (ဇ—၄ဝ၂။ အစွောံ။) = “ပညာရှိယောကျာ်းသေနကကို မျက်မြင်ဒိဋ္ဌ ထင်ရှားစွာမြင်ရခြင်းသည်အလွန်မြတ်၏။” || ‘ဂတမတ်ဇၚ်ဇၚ်’ (ကြိဝိ) လည်းရှု။')
,(7755,3,1,'ဆွဲတောင်း။',NULL)
,(7756,3,9,'(ကြိရှေ့ဆက်) ကြိယာကိုလေးနက်အောင် ထောက်ပံ့သောစကားလုံး။ —လတ်သော်။—သည်ရှိသော်။','နကြိက္တဵုဒှ် = ဖြစ်ပေါ်သည်ရှိသော်။ ဖြစ်ပေါ်လတ်သော်။ || “ပိုန်ဟာန်ဣန်သွဵုဂှ်နကြိလီုမ္ဂး ညံၚ်ရဴက္ၜၚ်မပါ်အာ ဒေါဝ်မှာသၟိတ်တုဲ မသက်သၞေဟ်သြၚ်စ္ၜုဲစ္ၜော်ဂှ် မဒးဒှ်ရ။” (ဇ—၃၅၃။ အစွောံ။) = “စည်းစိမ်အာဏာသည် ပျက်စီးလတ်သော် သမုဒ္ဒရာလယ်­ သင်္ဘောကွဲဘိသကဲ့သို့ တည်ရာကိုမရသည်ဖြစ်၏။” || “ယွံသၟိၚ်၊ ယြဴပၞတ်မွဲဂှ် နကြိက္တဵုဒှ်တုဲ နူဒတုဲမြမောဝ်ဇကုကီု ဒတုဲမြမောဝ်ညးကီု ဟွံဂွံညာတ်ရ။” (ဇ—၄၄၃။ အစွောံ။) = “ရေမြေသေဉ်နင်း ပြည့်ရှင်မင်း၊ အကြင်အမျက်သည် ဖြစ်လတ်သော် မိမိအကျိုး သူတစ်ပါးအကျိုးကို မမြင်။” (ညောင်ကန်)')
,(7757,3,9,'—လတ်သော်။ —သည်ရှိသော်။','“အတ္ထေ၊ ၚ်အရာကိစ္စမဝါတ်ဂါတ်လောန်။ ဇာတေ၊ နကြိက္တဵုဒှ်တုဲနေဝ်။ ပဏ္ဍိတံ၊ န်ညးမၞုံကဵုပညာ။ ဣစ္ဆန္တိ၊ ပ္ဍံနွံပၟိက်အိုတ်။” =“ခက်ခဲသောပြဿနာဖြစ်လတ်သော် ပညာရှိကို အလိုရှိကုန်၏။” || ‘နေဝ်’ လည်းရှု။')
,(7758,3,1,'ပိတောက်ပၚ်။','ပ္ကဴနဍူ = ပိတောက်ပန်း။')
,(7759,3,10,'(န) မြစ်။ နဒီ။',NULL)
,(7760,3,5,'ဘယ်နည်းအားဖြင့်။ ဘယ်လို။','“နနဲသာ်လဵု လမာဲဝွံ မဂွံရပ်နၚ်သၟိၚ်နာ်ဝွံမ္ဂးရော။” (ဇ—၅ဝ၆။ အစွောံ။) = “ဤအလမ္ပာယ်သည် နဂါးမင်းကို ဘယ်လိုဖမ်းယူရလာခဲ့သနည်း။”')
,(7761,3,5,'ဤနည်းအားဖြင့်။','“ပဟိုတ်သၟိက်ဂွံဗြဴသွဝ်တုဲရောၚ် မပၟဝ်ဓဝ်ခမဳရောၚ်သွံနန္ဒ” ဂးသာ်ဂှ်တုဲ တိပိုန်သာရိပိုန် ဟီုထဍိုက်ကၠေံနန္ဒရ၊ ဟီုပျုတ်ပမာကၠေံရ။ နနဲသာ်ဝွံ အိုတ်ဇၟာပ်ထေရ်ဇၞော်တံဂမၠိုၚ် ဟီုဖျောံဂဝကၠေံနန္ဒရ။ (ဇ—၁၈၂။ အစွောံ။) = “နတ်သမီးရလိုခြင်းကြောင့် ရဟန်းတရားကို အားထုတ်သည်ဆိုပါလားနန္ဒ” ဟု အရှင်သာရိပုတ္တရာသည် နန္ဒမထေရ်အား နှိပ်၍ ပြော၏၊ ရှုတ်ချ၍ပြော၏။ ဤနည်းအားဖြင့် အလုံးစုံသောမထေရ်ကြီးတို့သည်လည်း နန္ဒမထေရ်အား ရှက်ရအောင် ပြောဆိုကြကုန်၏။')
,(7762,3,11,'(န) (သဒ္ဒါ) အထီးအမသဘာဝ မရှိသောနာမ်။ နပုလ္လိင်။',NULL)
,(7763,3,11,'(န) နပုံသကပဏ္ဍုက်။ နပုန်းပဏ္ဍုက်။ ယောကျာ်းလည်းမဟုတ် မိန်းမလည်းမဟုတ်သူ။ လိၚ်မထင်ရှားသူ။','“မၞိဟ်နပုံသကပဏ္ဍုက် မၞိဟ်တြုံဟွံသေၚ် မၞိဟ်ဗြဴဟွံသေၚ်မကဵုတောမ် (ပုၚ်ဂှ်) ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “မိန်းမ၊ ယောကျာ်းမဟုတ်ဟု ဆိုသောကြောင့် နပုံသကပဏ္ဍုက်ကို (ထမင်းချက်စေ၏။)” (မင်းပူးဦးသြဘာသ)')
,(7764,3,4,'ဦးညွတ်သည်။','‘လမောဝ်’ လည်းရှု။')
,(7765,3,10,'(န) အချိန်အတိုင်းအတာ။',NULL)
,(7766,3,4,'‘လရု’ ရှု။',NULL)
,(7767,3,11,'(န) ငရဲ။','သတ်နရက် = ငရဲသား။ || ပၟၚ်နရက် = ငရဲစောင့်။ || နရက်အဝိက်= အဝီစိငရဲ။')
,(7768,3,4,'‘လရိုက်’ ရှု။',NULL)
,(7769,3,4,'ခိုၚ်အောင်လုပ်သည်။','‘ပခိုၚ်နရိုၚ်’ = ခိုၚ်ခန့်အောင်လုပ်သည်။ || ပခိုၚ်နရိုၚ်စိုတ်၊ ပခိုၚ်စိုတ်၊ နရိုၚ်စိုတ် = စိတ်ခိုၚ်အောင်ထိန်းချုပ်သည်။')
,(7770,3,4,'စိတ်ကိုခိုၚ်အောင်ထိန်းသည်။','‘ပခိုၚ်စိုတ်’၊ ‘ပခိုၚ်နရိုၚ်စိုတ်’ နှင့်အတူတူ။ || “ဂၞကျာ်ညာတ်တလးစရာဲဗောဓိသတ်တုဲ ဟိုတ်နရိုၚ်စိုတ်ဟွံမာန်တုဲ ‘ယွံအာစာ၊ ညံၚ်တိုန်လတူဒေန်အဲဝွံရ’ ဂၞကျာ်ဂး။” (ဇ—၁၂ဝ။ အစွောံ။) = “ဘုရားလောင်း၏ တင့်တယ်စမ္ပယ်ခြင်းကို မြင်ရသောမိဖုရားသည် မိမိစိတ်ကို ခိုၚ်အောင်မထိန်းနိုင်သောကြောင့် ‘ဆရာ၊ အိပ်ရာပေါ်သို့ တက်ပါလော့’ ဟု ဘုရားလောင်းအားခေါ်၏။”')
,(7771,3,4,'၁။ ဝမ်းနည်းကြေကွဲသည်။ ပူပန်သည်။ ကြောင့်ကြသည်။','“ညးကၠေၚ်ဏာကောန်တြုံဥတ္တရသေဋ္ဌဳဂှ် ညးဏာဂစိုတ်ရဂးတုဲ ပရိုၚ်ဂှ် တမ္ညဝ်အာအလုံဍုၚ်တံဂှ်ရ။ ဇန်တံညးဂမၠိုၚ် ဇွိတ်သြိုဟ်တုဲ နရာတ်တဴအိုတ်ရ။” (ဇ—၁၁၈။ အစွောံ။) = “ဥတ္တရသူဋ္ဌေးသားအား လက်ပြန်ကြိုးတုပ်လျက် (ဘုရင်၏လူများ) သတ်ရန်ခေါ်ဆောင်သွားရာ ထိုသတင်းသည် တစ်မြို့လုံးသို့ ပျံ့နှံ့ချောက်ချားသွား၏။ လူများသည် ရင်ကိုသပ်လျက် ဝမ်းနည်းကြေကွဲကြကုန်၏။” || “ဨကရာတ်နာဲပိုဲ ကဵုဂွံဗၠးနူသ္ကေံတဲသတြုညိ။ ဒေဝတဴတံ ဆောံမဒ္ဂူမၚ်မွဲဨကရာတ်နာဲပိုဲညိ” ဂးတုဲ ညးၜါဂှ် နရာတ်တဴရ။ (ဇ—၂၈၉။ အစွောံ။) = “ငါတို့အရှင်မင်းမြတ်သည် ရန်သူ့လက်တွင်းမှ လွတ် မြောက်ပါစေသတည်း။ ငါတို့အရှင်မင်းမြတ်အား နတ်အပေါင်းတို့ စောင််မစောင့်ရှောက်ကြပါစေသတည်း” ဟုဆို၍ ထိုသူနှစ်ဦးတို့သည် စိုးရိမ်ပူပန်ကြကုန်၏။ || “သေထဳနရာတ်၊ ညာတ်ကောန်ချိုတ်အာ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “သူဋ္ဌေးသည် သားသေသည်ကိုမြင်၍ ဝမ်းနည်းကြေကွဲ၏။” || “ဒှ်တဴဍိက်ညး၊ ဒးတဟးဒြာတ်။ ဒဒိုက်ကြုဲကြာဲ၊ လမ်လာဲနရာတ်။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “သူတစ်ပါး၏ကျွန်ဖြစ်၍ ကုန်းကောက်စရာမရှိအောင် ဆင်းရဲနွမ်းပါးလွန်းသောဒုက္ခဖြင့် ပူပန်ကြောင့်ကြ ဗျာများနေရ၏။” || “ပ္ဍဲစိုတ်စံၚ်တူ၊ ပူဆာနရာတ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်) = “စိတ်ထဲ­ပူလောင်၍ ပူပန်ကြေကွဲ၏။”')
,(7771,3,4,'၂။ ညည်းညူသည်။ အော်ဟစ်သည်။','“စိၚ်ဂှ် ဖေက်ဒဇပ်ဇတဝ်တဴတုဲ နရိုက်လပှ်တုဲ ဒြေပ်နရာတ်တဴရ။” (ဇ—၁ဝ၅။ အစွောံ။) = “ထိုဆင်သည် ကြောက်ရွံ့တုန်လှုပ်သည်ဖြစ်၍ နှာမောင်းကိုလှုပ်၍အော်ဟစ်လျက်ပြေး၏။” || “ပ္တုပ်ညးယဲက္ဍၚ်၊ သီုမသ္တၚ်ဂၠဝ်။ နရာတ်ဇတဝ်၊ တသဝ်ဇဝဴ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “ရောဂါသည်းသောလူနာဟန်ဆောင်၍ လဲလျောင်းလျက်နေကာအော်ဟစ်တုန်လှုပ်လျက် ညည်းညူညည်းတွား၏။”')
,(7771,3,4,'၃။ မြည်ဟည်းသည်။','“အိုတ်ကဵုစှ်လ္ၚီလောကဓါတ် နရာတ်ဗြုကြဵု က္တဵုဒှ်ကသဳတိ။” (ဗုဒ္ဓဝၚ်။ မာံရွှေငိုး။) = “အလုံးစုံသော စကြဝဠာတိုက်တစ်သောင်းသည် မြည်ဟည်းထစ်ချုန်းလျက် မြေၚလျှင်ဖြစ်ပေါ်၏။”')
,(7771,3,4,'၄။ ပူလောင်သည်။','“တ္ၚဲမဒှ်ၜါ၊ တုပ်ပမာဏ။ ဟိုတ်မက္တဴကာတ်၊ နရာတ်ကာယ။” (လိက်ပဒုမဝတဳ) =“နေနှစ်စင်းထွက်သည့်ပမာ ပူပြင်းလွန်းသောကြောင့် ကိုယ်ကာယပူလောင်၏။”')
,(7772,3,4,'ငိုသည်။','‘လရိုအ်’ ရှု။')
,(7773,3,10,'(နဝိ) ကိုးခုမြောက်။',NULL)
,(7774,3,12,'(န) နဝင်း။ တစ်ရာသီ၏ကိုးစိတ်တစ်စိတ်။','“ပံက်ဂြန်ရံၚ်ဗေဒၚ်၊ နဝၚ်သီုဒိတ္ထဳ။” (လိက်ဂၞကျာ်ဝိသာခါ) = “နည်းနာကိုဖွင့်၍ ဗေဒင်၊ နဝင်းနှင့် လဆန်းလဆုတ်ရက်တို့ကို ကြည့်၏။”')
,(7775,3,1,'ညောင်စောင်း။ ခုတၚ်။',NULL)
,(7776,3,5,'လှိုက်လှဲစွာ။ ပျူငှာစွာ။','“ဝေၚ်ဒုၚ်တဴညိ၊ နသိနလ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “လှိုက်လှဲပျူငှာစွာ ကြိုဆိုသည်။” || “(ကုသၟိၚ်မရာံဒှ်ခရှ်ဂှ်) သေဏာပတိ၊ နသိနလ။အမာတ်တံကီု၊ သီုကဵုထဒၟ။ ဒတဲပ္တိုန်ဏာ၊ တူပြာသာတ်မြ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “ရဟန်းအဖြစ်မှ လူဝတ်လဲသောမင်းကို သေနာပတိက လှိုက်လှဲပျူငှာစွာကြိုဆို၍ အမတ်အပေါင်းတို့က ရိုသေလေးမြတ်စွာဖြင့် မြနန်းပြာသာဒ်ထက်သို့ တွဲခေါ်တၚ်ကြကုန်၏။” || “ဒ္ၚဳတီကေတ်ပၠန်၊ ကောန်ဨကရာတ်။ နသိနလ၊ ထဒၟခပ်ပြာတ်။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “ဘုရင့်သားတော်ဖြစ်ကြောင်း သိရသည်ရှိသော် လှိုက်လှဲပျူငှာ ရိုသေလေးမြတ်စွာ ကြိုဆိုဆက်ဆံ၏။”')
,(7777,3,4,'ရွှင်လန်းဝမ်းမြောက်သည်။ ကြည်သာရွှင်ပျသည်။','“ညံၚ်ကောန်ညာတ်မိ၊ နသိနသောန်။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “အမိကိုမြင်သော သားငယ်ကဲ့သို့ အလွန်ရွှင်လန်းဝမ်းမြောက်၏။”')
,(7778,3,1,'တင်းတောင်း။ တစ်ဆယ့်ခြောက်ပြည်ပမာဏရှိသော အခြင်အတွယ်တောင်း။',NULL)
,(7779,3,11,'(န) တစ်သောင်း။ (ပါဠိ—နဟုတ)','‘လဟုတ်’ ဟုလည်းရေးသည်။')
,(7780,3,9,'(လက်ဟန်ခြေဟန်ပြလျက်) နာသူ၏အာရုံကို ရယူသည့်သဘောဖြင့် သုံးသောစကား။ဟော—။','“ဟီုဟွံကလၚ်တှ်ေ နာ—လေံၜဝ်ဏအ်ရံၚ်လဝ်။” = “ပြောတာကိုနားမထောင်ရင်ဟောဒီကြိမ်လုံးကို ကြည့်ထား။” || “ကၠောန်ဟွံလေပ်တှ်ေ ရံၚ်လဝ်၊ နာ—ဗီုဏအ်ကၠောန်။” =“မလုပ်တတ်ရင် ကြည့်ထား၊ ဟောဒီလိုလုပ်။” || “အပေါတ်အဲဂၠာဲဒၟံၚ်ဂှ် နာ—ဣဏအ် ဆဵုဣရ။”= “ငါရှာနေတဲ့ပစ္စည်း ဟောဒီမှာတွေ့ပြီ။”')
,(7781,3,1,'၁။ နာဂလူမျိုး။ (တိဗက်မြန်မာအုပ်စုဝင် ဘာသာစကားတစ်မျိုးကိုပြောသော မြန်မာတိုင်းရင်းသားတစ်မျိုး။)',NULL)
,(7781,3,10,'(န) ၂။ ဆင်။',NULL)
,(7781,3,10,'(န) ၃။ နဂါး။',NULL)
,(7782,3,11,'(န) မြို့။ နဂိုရ်။ နဂရ။',NULL)
,(7783,3,1,'ပိုးကရင်။','ကရေၚ်နာဍိ = ပိုးကရင်။')
,(7784,3,16,'(န) ၁။ နာရီ (အချိန်ပြကိရိယာ) ။','နာဍဳၜါမ = နာရီနှစ်လုံး။')
,(7784,3,16,'(န) ၂။ (ရှေးသုံး) တစ်ရက်၏ခြောက်ဆယ်ပုံတစ်ပုံ။',NULL)
,(7784,3,16,'(န) ၃။ (ယနေ့ခေတ်သုံး) တစ်ရက်၏နှစ်ဆဲ့လေးပုံတစ်ပုံ။ မိနစ် (၆ဝ) ။',NULL)
,(7785,3,1,'ပေါက်ပေါက်နှင့်လုပ်သောမုန့်။ မရွေးမုန့်။ ထမင်းခြောက်ကို သကာသကြားတို့နှင့်ရော၍ အဆုပ်လုပ်ထားသောမုန့်။','“(သမ္ဘာဗမၞးဂှ်) နာဍူကီု ဂၜိုဟ်ကီု ကၠောန်တုဲ စုတ်ပ္ဍဲဖျေဲသၞာံတုဲဇိုန်ကဵုဗမၞးရ။” (ဇ—၄ဝ၂။ အစွောံ။) = “ပုဏ္ဏေးမသည် ပုဏ္ဏားအို၏သားရေအိတ်­ အဆုပ်ဖွဲ့အပ်သောမုန့်တို့ဖြင့်လည်းကောင်း အဆုပ်မဖွဲ့အပ်သောမုန့်တို့ဖြင့်လည်းကောင်း ပြည့်စေ၍ပေး၏။” (ညောင်ကန်) || “ဂၠာဲစဳရေၚ်ပ္ညုၚ်၊ ပုၚ်နာဍူရောၚ်။” (လိက်မၚ်ဗၠာဲသ္ၚိတူ)')
,(7786,3,10,'(န) ကာကွယ်သူ။ စောင့်ရှောက်သူ။ အကြီးအမှူး။','“နာဲသာဂေါတမ၊ မစိုန်ဒှ်ရော၊ကြိလောကနာထ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “သုံးလောကထွတ်ထားဖြစ်တော်မူထသော ဂေါတမမြတ်စွာဘုရား။”')
,(7787,3,11,'(နဝိ) (ကဗျာသုံး) ကိုးကွယ်ရာမရှိသော။ အားကိုးရာမရှိသော။ ဆင်းရဲသော။','‘အနာထ’ နှင့်အတူတူ။ || “ဒိုက်ဒိန်ဇြေဟ်ဇြာဲ၊ လောန်ကာဲက္ဍၚ်ပြ။ ဒၞာဲချပ်ဂၞန်၊ ဇၟာပ်ကၠောန်ၜိုတ်စ။ ဟွံဒှ်ညံၚ်စိုတ်၊ ဍောၚ်ၜိုတ်နာထ။” (လိက်ကာလထေ) = “အလွန်အမင်းဆင်းရဲနွမ်းပါးပိန်လှီ၏၊ ကြံစည်လေရာရာ လုပ်ကိုင်လေရာရာ စိတ်တိုင်းကျမဖြစ်ဘဲ ပင်ပန်းဆင်းရဲ၏။” || “ဒိုက်ဂတ်နာထ၊ ဝဳပါကဂြဲ။” (လိက်ကာလထေ) = “ဝိပါက်ကြောင့် ဆင်းရဲနွမ်းပါးအားကိုးရာမဲ့၏။”')
,(7788,3,10,'(နဝိ) အမျိုးမျိုးသော။','နာနာသာ် = အမျိုးမျိုး။ || ကွာၚ်နာနာသာ် = မုန့်အမျိုးမျိုး။ || “ကဵုပ္ကောံနၚ်စၞအာဟာရဘောဇိုန် နာနာသာ်တုဲ—။” (ဇ—၅၃၂။ အစွောံ။) = “အမျိုးမျိုးသော အစာအာဟာရဘောဇဉ်တို့ကို စုစည်းယူဆောင်စေ၍—။” || “တိချဳသဓဵု၊ ဗြုကြဵုနာနာ။” (လိက်ရတနပဇ္ဇောတ) = “မြေကြီးလှုပ်ခတ်၍ အမျိုးမျိုးမြည်ဟည်းနေ၏။”')
,(7789,3,10,'(န) ၁။ သေကွဲကွဲခြင်း။',NULL)
,(7789,3,10,'(န) ၂။ တစ္ဆေ၊ သရဲစသော မကောင်းဆိုးဝါး။',NULL)
,(7790,3,10,'(န) အမည်။ နာမည်။ နာမ။',NULL)
,(7791,3,10,'(သဒ္ဒါ) နာမ်ကိုအထူးပြုသောပုဒ်။ နာမဝိသေသန။',NULL)
,(7792,3,10,'(န) အကြီးအမှူးဖြစ်သူ။ နာယက။',NULL)
,(7793,3,11,'(န) နာယကဂုဏ်။ (အကြီးအမှူးဖြစ်သူတို့တွင် ရှိအပ်သောအရည်အချင်း။) (၁၊ ခမာ = သည်းခံခြင်း။ ၂၊ ဇာဂရိယ = နိုးကြားခြင်း။ ၃၊ ဥဋ္ဌန = ထကြွလုံ့လရှိခြင်း။ ၄၊သံဝိဘာဂ = ခွဲခြမ်းဝေဖန်ခြင်း။ ၅၊ ဒယာ = သနားကြင်နာခြင်း။ ၆၊ ဣက္ခနာ = မြော်မြင်ဆင်ခြင်ခြင်း ဟူ၍ခြောက်ပါးရှိသည်။)',NULL)
,(7794,3,10,'(န) တစ်တင်း၏ရှစ်ပုံတစ်ပုံ ပမာဏအတိုင်းအတာ။',NULL)
,(7795,3,11,'(န) နာသိကဋ္ဌာန်။ အချို့အက္ခရာတို့ အသံဖြစ်ပေါ်ရာ နှာခေါင်းအရပ်။',NULL)
,(7796,3,10,'(န) အပေါင်းအစု။ ဂိုဏ်း။',NULL)
,(7797,3,11,'(န) နိကာယ်။ (ဘုရားဟောပါဠိတော်များကို သုတ်ရှည်၊ သုတ်လတ်၊ သုတ်ငယ်စသည် စုပေါင်းထားသော သုတ်အစုအပေါင်း။) (ဒီဃနိကာယ်၊ မဇ္ဈိမနိကာယ်၊ သံယုတ္တနိကာယ်၊အင်္ဂုတ္တရနိကာယ်၊ ခုဒ္ဒကနိကာယ်ဟူ၍ ငါးပါးရှိသည်။)',NULL)
,(7798,3,11,'(န) နိဂုံး။ ဈေးသာရှိ၍ မြို့ရိုးမရှိသောအရပ်။ ဈေးမြို့။ (ပါဠိ—နိဂမ)','“အာစိုပ်နဳဂီုမွဲ ပ္ဍဲရးကသဳကရးဂှ်—။” (ဇ—၃၂၈။ အစွောံ။) = “ကာသိတိုင်းရှိ တစ်ခုသောနိဂုံးရွာသို့ ရောက်သည်ရှိသော်—။” || “ဗောဓိသတ်ပိုဲ ဒှ်ကောန်ဗမၞး ပ္ဍဲကွာန်နဳဂီုမွဲရ။” (ဇ—၄ဝ၃။အစွောံ။) = “ဘုရားလောင်းသည် တစ်ခုသောနိဂုံးဝယ် ပုဏ္ဏားမျိုး­ဖြစ်၏။” (ညောင်ကန်)')
,(7799,3,11,'(န) နိဂုံး။ အဆုံးသတ်စကား။ (ပါဠိ—နိဂမန)','အုပ်နိဂီု = နိဂုံးချုပ်သည်။')
,(7800,3,10,'(န) ညောင်ပင်။',NULL)
,(7801,3,10,'(န) အကြောင်း။ နိဒါန်း။','“ဗောဓိသတ်ပၠန် တၞဟ်နကဵုသၟိၚ်တီတုဲ နိဒါန်မွဲဇက်နၚ်ပၠန်ရ။” (ဇ—၄၃၂။ အစွောံ။) = “ဘုရားလောင်းသည် မင်းအားသိစိမ့်သောငှာ တစ်ခုသောအကြောင်းကို ဆောင်ပြန်၏။” || “တရးဟွံမာန်၊ နဳဒါန်ဂြိုပ်ဝွံ။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်။) = “ဤတော၏အကြောင်းကို အကျယ်ဆိုခြင်းငှာ မတတ်နိုင်။”  || “တန်ကော်ကလုတ်တံတုဲ တန်သၟာန်သၟုက်နဳဒါန်အိုဿီုရအဴ။” (သၠပတ်ရာဇာသာန်) = “တမန်တို့အားခေါ်သင့်ပြီး အကြောင်းအလုံးစုံကို မေးမြန်းသင့်၏။” || “ခါဗောဓိသတ်၊ တြုံကၞတ်ညာန်။ တီကေတ်ကွေံကြာန်၊နဳဒါန်ဟိုတ်ဖဵု။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “ဉာဏ်အထွတ်အထိပ်ယောကျာ်း ဘုရားလောင်းသည် ထိုအကြောင်းရင်း အကြောင်းအကျိုးကို အမှန်တကယ်သိ၏။”')
,(7802,3,1,'ရောဂါ၏အကြောင်းရင်း။','“ယဝ်ရဟွံလေပ်ပြကိုဟ် ဟွံတီနဳဒါန်ယဲကဵုဂအုဲဟွံဒး။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “အကယ်၍ကျမ်းမတတ် ရောဂါအကြောင်းရင်းကို မသိပါက ဆေးမှန်အောင်မပေးနိုင်။”')
,(7803,3,10,'(န) (မြှုပ်နှံထားသော) ဥစ္စာအိုး။ ရွှေအိုး။','“ယွံဗမၞး၊ ဆုဇြဲၜိုၚ်မတဴဂတဆုမုက်ဂှ် ပ္ဍဲဝုတ်ဒိုဟ်တၞံဆုဇြဲၜိုၚ်ဂှ် နိဓိဂၠိုၚ်သန်ရ။ ညးမတိုပ်လဝ် အာဲကၟာဲညးတရေံ ဟၟဲကဵုတလရ” ဒေဝတဴဂး။ (ဇ—၃ဝ၇။ အစွောံ။) = “အချင်းပုဏ္ဏား၊ တည်ပၚ်၏ရှေ့­ရှိသော ညောင်ကြတ်ပၚ်၏ဝန်းကျင်­ရွှေအိုးတို့သည် များလှစွာ၏။ သူဟောင်းတို့မြှုပ်ထားအပ်သော ပိုင်ရှင်မရှိသော အမွေအနှစ်တည်း” ဟုရုက္ခစိုးနတ်ဆို၏။ || “ညံၚ်ဒိုက်ဂတ်မကလိဂွံနိဓိကီု။” (သၠပတ်စန္ဒဝတဳ) = “ရွှေအိုးကိုရရှိသော သူဆင်းရဲကဲ့သို့။”')
,(7804,3,11,'(န) နိပါတ်။ (မြတ်စွာဘုရား၏ ရှေးဘဝအဖြစ်အပျက်ဇာတ်တော်များကို ဂါထာအရေအတွက်အလိုက် စုစည်းထားသော ဇာတ်ဝတ္ထုအစု။)',NULL)
,(7805,3,11,'(န) ၁။ နိမိတ်။',NULL)
,(7805,3,11,'(န) ၂။ (ယောကျာ်း၊ မိန်းမ) အင်္ဂါဇာတ်။','နိမိတ်တြုံ = ယောကျာ်းအင်္ဂါဇာတ်။ || နိမိတ်ဗြဴ = မိန်းမအင်္ဂါဇာတ်။')
,(7806,3,1,'နိမိတ်ကြီးလေးပါး။ (ဘုရားလောင်းသိဒ္ဓတ္တမင်းသားအား သံဝေဂဖြစ်စေသည့် သူအို၊ သူနာ၊ သူသေ၊ ရဟန်းဟူသော နိမိတ်ကြီးလေးမျိုး။)',NULL)
,(7807,3,4,'ဖန်ဆင်းသည်။','“ကလော်တံဂှ် ယာန်ကွဳစောတ်မဂပ်ဂဝ်လှိၚ်စိုတ် မဗ္ဂန်ကေတ်ဂၠဴဗၠာဲဗ္တာၚ်ဂှ် ဍေံနိမိတ်ဗဒှ်တုဲ (ဍေံဒစးကၠုၚ်ကဵုညးဗၞိက်ကွဳတံဂှ်ရ။)” (ဇ—၁။ အစွောံ။) = “ဘီလူးတို့သည် အလုံးစုံဖြူသော ပျိုသောနွားတို့ဖြင့်ကသော နှလုံးမွေ့လျော်ဖွယ်ရှိသောလှည်းယာဉ်ကိုဖန်ဆင်း၍ လှည်းကုန်သည်တို့ဆီသို့ ခရီးရင်ဆိုင်အရပ်မှ လာကြကုန်၏။” || ‘လၟိတ်ဗဒှ်’ နှင့်အတူတူ။')
,(7808,3,1,'နိမိတ်။ အတိတ်နိမိတ်။ နိမိတ်ကြီးနိမိတ်ငယ်။','နိမိတ်သၞဲဟွံခိုဟ် =နိမိတ်မကောင်း။ အတိတ်နိမိတ်မကောင်း။')
,(7809,3,11,'(န) (ရဟန်းကို) ပင့်ဖိတ်ခြင်း။ (လူကို) ဖိတ်ကြားခြင်း။ (ပါဠိ—နိမန္တန)','“ကြဴဝွံ ဒးနိမန်ညးဒုၚ်မ္ၚဵု—။” (ဇ—၁၂၃။ အစွောံ။) = “နောက်­ ပရိတ်မင်္ဂလာပြုရန် ပင့်ဖိတ် ခြင်းခံရ၏။”')
,(7809,3,11,'(န) (ကြိ) ပင့်ဖိတ်သည်။ ဖိတ်ကြားသည်။','“ညးဂမၠိုၚ်ညာတ်ညးၜါတုဲ နိမန်ပ္တိုန် (လတူသ္ၚိရ။)” (ဇ—၃၇၈။ အစွောံ။) = “လူများသည် ထိုသူနှစ်ယောက်ကိုမြင်၍ အိမ်ပေါ်သို့တက်ရန် ပင့်ဘိတ်ကုန်၏။” || “ညးဗၞိက်မသုန်ကၠံကွဳဂှ် ဍေံတံနိမန်ကျာ်သီုသၚ်တုဲ ဍေံတံဖါပ်ကဵုဒါန်ရ။” (ဇ—၄၉၃။ အစွောံ။) = “ငါးရာကုန်သော လှည်းကုန်သည်တို့သည် မြတ်စွာဘုရားနှင့်တကွ သံဃာတော်တို့ကို ပင့်ဖိတ်၍ဆွမ်းကျွေး၏။” || ‘လၟန်’ နှင့်အတူတူ။')
,(7810,3,10,'(နဝိ) ဝဋ်ဆင်းရဲမှ ထွက်မြောက်ကြောင်းဖြစ်သော။ သံသရာမှ ထွက်မြောက်ကြောင်းဖြစ်သော။','“ယွံခမဳ၊ — လၟုဟ်ဂွံဆဵုသာသနာအဲ နိယာနိက ဇိုန်ကဵုသွဝ်ဗြီုနိဗ္ဗာန်ရောၚ်။မူပတလအဲထောံကၠေံလွဳရော” ကျာ်တြဲဂး။ (ဇ—၂။ အစွောံ။) = “ရဟန်း၊ — နတ်ဗြဟ္မာနိဗ္ဗာန်ကို ဆောင်ကြဉ်းပေးတတ်သော ဝဋ်ဆင်းရဲမှ ထွက်မြောက်ကြောင်းဖြစ်သော ငါ၏သာသနာတော်­ ဝီရိယကို အဘယ်ကြောင့်လျှော့သနည်း။”')
,(7811,3,10,'(န) သဘာဝဖြစ်ရိုးဖြစ်စဉ်။ ဖြစ်မြဲသဘော။ နိယာမ။',NULL)
,(7812,3,1,'မြှားကျည်။','“နဳရာဲချတ်ဂၞိၚ်၊ ၜုန်နိၚ်ရပ်ဏာ။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်) = “မြှားကျည်ကို ခါးကြားထိုး၍ ဓါးမြောင်ကို ကိုင်ဆောင်သွားသည်။”')
,(7813,3,11,'(ဂဏန်း) တစ်ကုဋေ။','“ဗောဓိသတ်ပတၠသ္ဂေဟ် ဒစာံစှ်ောနိလဟုတ် သၚ်ခသေဋ္ဌဳဒုၚ်ယၟု။” (ဇ—၁၃၁။ အစွောံ။) = “ဘုရားလောင်းသည် ကုဋေရှစ်ဆယ်ကြွယ်သော စည်းစိမ်ရှင်ဖြစ်၍ သင်္ခသူဋ္ဌေးဟု အမည်တွင်၏။” || “သေဋ္ဌဳတၠသ္ဂေဟ်မွဲ ဒြပ်မတိုပ်ဒေပ်လဝ် ပန်စှ်ောနိလဟုတ်။” (ဇ—၁၃၇။ အစွောံ။) = “တစ်ယောက်သောသူဋ္ဌေးသည် ကုဋေလေးဆယ်သောဥစ္စာတို့ကို မြှုပ်နှံထား၏။” || ‘ကိုတ်/ကိုဋ်’ လည်းရှု။')
,(7814,3,1,'ဆယ်ကုဋေ။',NULL)
,(7815,3,10,'(န) မိမိကိုယ်ကို နှိမ့်ချခြင်း။ နိဝါတ။',NULL)
,(7816,3,11,'(န) အတားအဆီး။ တားမြစ်ခြင်း။ ပိတ်ပင်ခြင်း။ နိဝရဏတရား။ (ပါဠိ—နဳဝရဏ)','နိဝဵုမသုန် = နိဝရဏတရားငါးပါး။')
,(7817,3,11,'(န) ထိုင်စရာအခင်း။ နိသီဒိုန်။ (ပါဠိ—နိသီဒန)',NULL)
,(7818,3,10,'(န) အကျိုးဆက်။','“(ပ္ဍဲဘဝအတိက်တေံ ဟိုတ်မၜုၚ်တက်လဝ် မိမဒမၠုမတ်တံဂှ်တုဲ) ဟိုတ်နိသန္ဒဝဳပက်ဂှ် ပ္ဍဲကၞောတ်ဘဝဝွံဂှ် ဝဳပက်ဂှ် ဍေံကၠုၚ်ကဵုဖဵုတုဲ ဒမၠတံၜုၚ်တက်ဂစိုတ်ကၠေံထေရ်ရောၚ်။” (ဇ—၅၂၂။ အစွောံ။) = “အတိတ်ဘဝက မျက်မမြင်မိဘတို့အား ရိုက်ပုတ်ပြစ်မှားမိသဖြင့် ထိုဝိပက်၏အကျိုးဆက်ကြောင့် အဆုံးစွန်သောဘဝ­ ထိုဝိပက်အကျိုးလာပေးသဖြင့် ဓါးပြများ၏ရိုက်သတ်ခြင်းကို မထေရ်ခံရလေ၏။” || “ဟိုတ်နိသန္ဒဝဳပက်သရာံပါပ်ဂှ်တုဲ အဲဍိက်မက္တဵုဒှ်ယဲတၞီဝွံရအဴ။” (ဇ—၅၁၆။ အစွောံ။) = “ထိုမကောင်းမှုဝိပက်ကံအကျိုးဆက်ကြောင့်အကျွန်ုပ်သည် ဤနူနာရောဂါဖြစ်ရ၏။”')
,(7819,3,10,'(န) လမ်းညွှန်ဆုံးမသောစကား။ အဆုံးအမကျမ်း။ နီတိ။',NULL)
,(7820,3,11,'(န) ‘နိဒါန်’ ရှု။',NULL)
,(7821,3,11,'(န) ‘နိဗ္ဗာန်’ ရှု။',NULL)
,(7822,3,11,'(န) နီလာကျောက်။',NULL)
,(7823,3,6,'၁။ မှ။ က။','“ကၠုၚ်နူဍုၚ်ရေဝ်ရ။” = “ရေးမြို့မှလာသည်။”')
,(7823,3,6,'၂။ ထက်။','“ဍေံကျေဝ်နူအဲရ။” = “သူသည် ငါ့ထက်လှသည်။”')
,(7824,3,5,'ယခင်က။ ရှေးက။','“ဝဳပက်နူကိုပ်၊ ကၠုၚ်စိုပ်လမုဟ်။” (လိက်ရတနပဇ္ဇောတ) =“ရှေးကဝိပါက်သည် ယခုလာရောက်လေပြီ။”')
,(7825,3,5,'ခြေဆုံးခေါင်းဆုံး။ တစ်ကိုယ်လုံးအနှံ့။',NULL)
,(7826,3,5,'လွန်လာသောမကြာမီအချိန်။ ခုနက။','“အဲစိုပ်ကၠုၚ်နူကၠၚ်ဏအ်ရ။”= “ခုနကဘဲ ကျွန်တော်ရောက်လာတယ်။” || “ယွံသဟာဲပိုဲ (ကျာံ) ၊ သမ္ဘာတၠအဲသၟိက်ဂွံစဖျုန်ဂြိုဟ်အဲဂှ် နူလက်ကၠၚ် မူဟိုတ်ဟွံဟီုကဵုအဲရော” သၟိၚ်ကၞုဲဂး။ (ဇ—၃၄၂။ အစွောံ။) = “အဆွေမိကျောင်း၊ ငါ၏နှလုံးသားကို သင်၏မယားစားလိုသည်ကို ခုနက သၚ်ဘာကြောင့်မပြောပါသနည်း။” ဟုမျောက်မင်းဆို၏။ || “ယွံကောန်ပိုဲ၊ ပူဂဵုမအာကၠေံနူကၠၚ်ဂှ် သၟိၚ်နာ်သၚ်္ခပါလဂးယၟုရကောန်” ဣသိဂး။ (ဇ—၅၂၄။ အစွောံ။) = “ချစ်သား၊ ခုနကသွားသောပုဂ္ဂိုလ်သည် သင်္ခပါလမည်သောနဂါးမင်းတည်း။”')
,(7827,3,1,'နံနက်။','ပယာံနူဂယး = နံနက်အချိန်။ || နူဂယးပြဟ် = နံနက်စောစော။')
,(7828,3,3,'မွေးရာပါဖြစ်သော။','ယဲနူဂဝ် = မွေးရာပါရောဂါ။ || “ဂၠုမတ်နူဂဝ်၊ က္ဍိုၚ်နူဂဝ်ကၠာ။ဝေန်နူဂဝ်အဴ၊ ကၠဴနူဂဝ်မာ။ ဗၠးအိုတ်သေၚ်ဟာ၊ ပ္ဍဲကာလဂှ်။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) =“မွေးရာပါမျက်စိကန်းခြင်း၊ မွေးရာပါနားပင်းခြင်း၊ မွေးရာပါကိုယ်လက်အင်္ဂါဆွံ့ခြင်း၊ မွေးရာပါဆွံ့အခြင်းတို့သည် ထိုအခါပျောက်ကင်းကုန်၏။”')
,(7829,3,4,'အစမှအဆုံးအထိ။','“ဂလာန်သၟတ်ၜါမဟီုဂှ် ဇမၞော်ဒမာတ်ဂှ် မိၚ်ကေတ်နူတံဒဵုကၞောတ်ဂှ်တုဲ—။” (ဇ—၃၈၇။ အစွောံ။) = “သူငယ်နှစ်ဦးတို့ ပြောဆိုသောစကားကို ပန်းပဲဆရာကြီးသည် အစမှအဆုံးထိကြားရပြီးလျှင်—။”')
,(7830,3,5,'မနေ့က။','‘လက်တၞေအ်’ နှင့်အတူတူ။')
,(7831,3,5,'ဘယ်နေရာမှ။ ဘယ်က။','“နူလဵုမကၠုၚ်သ္ဂးရော။” (ဇ—၅၃၇။ အစွောံ။) = “ဘယ်ကလာပါသနည်း။” || “နူလဵုမကၠုၚ်၊ တလုၚ်အရာ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “ဘယ်ကလာသောလာခြင်းပါနည်း။”')
,(7832,3,6,'အထဲမှ။',NULL)
,(7833,3,16,'(န) အနောက်တောင်အရပ်။',NULL)
,(7834,3,11,'(န) နည်း။ လိုက်နာဖွယ်စနစ်။',NULL)
,(7835,3,1,'နည်းနာ။ နည်းလမ်း။ လိုက်နာဖွယ်နည်း။','“ဗြရတ်ဂၠိုက်ဂၠာဲ၊ ပြယာဲနဲကဲ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ဗြရတ်သည် ပရိယာယ်နည်းနာကို ရှာဖွေစုံစမ်း၏။”')
,(7836,3,11,'(န) အလဲအလှယ်နည်းလမ်း။ နည်းပရိယာယ်။',NULL)
,(7837,3,11,'(န) နည်းဗျူဟာ။ (စစ်ရေး၊ နိုင်ငံရေးစသည်တွင် ရည်မှန်းချက်တစ်ရပ်အောင်မြင်ပြီးမြောက်စေရေးအတွက် သက်ဆိုင်ရာအဖွဲ့အစည်း၏ စီစဉ်ခင်းကျင်းမှုဆိုင်ရာနည်းပညာ။)','‘မဟာဗျူဟာ’ လည်းရှု။')
,(7838,3,11,'(န) နည်း။ နည်းနာ။ (ပါဠိ—နယ)','“(မှာထေရ်သာရိပိုတ်ကီုလေဝ်) ကျာ်ကဵုနဲယျတုဲ မသှ်ဒးရောၚ်။” (ဇ—ဝိဓုရ။ အစွောံ။) = “အရှင်သာရိပုတ္တရာသည်ပၚ်လည်း မြတ်စွာဘုရားနည်းပေးမှ ဖြေဆိုနိုင်၏။” || ‘နဲယျအာစာ။’ (ပြကိုဟ်မ္ငိုလ်ပိစှ်ောဒစာံ) = ‘ဆရာ့နည်းနာ။’ || “သီုကဵုနဲယျ၊ တိတ်ပၠဝါစာ။” (လိက်ဇိဝှစက္က) = “နည်းနာနှင့်တကွ စကားထွက်ဆို၏။”')
,(7839,3,11,'(န) နည်းဥပဒေ။',NULL)
,(7840,3,4,'ပေါများသည်။ အနှံ့ပြန့်ကြဲသည်။','“ပုၚ်ဒတုံစှ်ေနးဒၟံၚ်—။” (ဇ—၃၈၆။ အစွောံ။) =“ထမင်းတုံးကျ၍ အနှံ့ပြန့်ကြဲနေ၏။” || “စိၚ်ချေံဒြေပ်နး၊ မၞိဟ်ပြးဇးအိုတ်။” (လိက်သၚ်ဂဒါ။သဳလဝန္တ။) = “ဆင်မြင်းတို့သည် အနှံ့ထွက်ပြေးပြန့်ကြဲ၍ လူများအုပ်စုကွဲသွားကြကုန်၏။” || “ကၠေပ်ထဝ်ဗာန်ထဝ်၊ သၠိုၚ်ထဝ်လစး။ လုံပြာသာဒ်နန်၊ ပေၚ်တ္ၜန်တ္ၜောဲနး။” (လိက်ဟတ္ထိပါလ။အစွောံ။) = “ရွှေကျိုင်း၊ ရွှေလင်ပန်း၊ ရွှေခွက်တို့သည် နန်းပြာသာဒ်အလုံး­ အရောင်ဖိတ်ဖိတ်တောက်ကုန်လျက် ပေါများ၍အနှံ့ပြည့်နှက်နေ၏။”')
,(7841,3,4,'လုံလောက်သည်။ ပေါများသည်။','“ဇွောအ်မနးပးတဴရ။” = “ရိက္ခာပေါကြွယ်၏။”')
,(7841,3,5,'အနှံ့အပြား။','‘လ္ပအာနးပးညိ။’ = ‘အနှံ့အပြားမသွားပါနှင့်။’')
,(7842,3,4,'နစ်သည်။','နက်ခရီု = ရွှံ့ညွန်တွင်နစ်သည်။')
,(7843,3,11,'(န) နဂါး၏ညွတ်ကွင်း။ (ပါဠိ—နာဂ×ပါသ)',NULL)
,(7844,3,11,'(နဝိ) နဂါးနှင့်ဆိုင်သော။','ဍုၚ်နက္ကဘဴ = နဂါးပြည်။ (ပါဠိ—နာဂ×ဘာဝ) || ‘နာက္ကဘဴ’ ဟု အချို့ရေးသည်။ || “သၟိၚ်ညာတ်ပိုန်ဟာန်သၟိၚ်နာ်ဂှ်တုဲ ဗွဲလောဘတဏှာဂှ် ထၞေန်တဴစိုတ်ကဵုဍုၚ်နက္ကဘဴတေံရ။” (ဇ—၅၂၄။ အစွောံ။) = “မင်းသည် နဂါးမင်း၏စည်းစိမ်ကိုမြင်၍လောဘတဏှာအားဖြင့် နဂါးပြည်ကို တပ်စွန်းသောစိတ်ရှိ၏။”')
,(7845,3,11,'(န) နက္ခတ်နှင့်ဆိုင်သောပညာ။ နက္ခတ္တဗေဒ။',NULL)
,(7846,3,10,'(နဝိ) ကိုယ်လုံးတီးဖြစ်သော။ အဝတ်မဆည်းသော။ ကိုယ်ချည်းဗလာ အဝတ်မပါသော။','(ညးဂမၠိုၚ်ညာတ်မၞိဟ်နဂ္ဂဂှ်တုဲ “ဂမှဳဝွံမွဲ အပ္ပိစ္ဆာဂုန်ရောၚ်၊ သန္တုတ္ထဳဂုန်ရောၚ်” ဂးတုဲ ညးယိုက်ဒိုက်တုဲ ပူဇဴသကာဗွဲမဂၠိုၚ် ညးကဵုရ။) (ဇ—၅၁၈။ အစွောံ။) = (လူတို့သည် အဝတ်မပါ ကိုယ်ချည်းဗလာဖြစ်သောလူကို မြင်သည်ရှိသော် “ဤရဟန်းကား အလိုနည်း၏။ ရောင့်ရဲလွယ်၏”ဟု ချီးမွမ်းကုန်၍ ပူဇော်သက္ကာရကို ပြုကုန်၏။)')
,(7847,3,1,'လက်နက်။',NULL)
,(7848,3,12,'(န) နက္ခတ်။ တာရာ။',NULL)
,(7849,3,11,'(န) နဂါး။ (ပါဠိ—နာဂ)',NULL)
,(7850,3,11,'(န) နိက္ခ။ ရွှေစင်အလေးချိန်တစ်မျိုး။ (၂၅) ကျပ်သားနှင့်ညီမျှသည်။','“(၂၅) ဒကေဝ် ဒှ်မွဲနိက်။ (၄) နိက် ဒှ်မွဲပသာ။” သၠပတ်နိယမ (၅) နဲ (၁၅) = “(၂၅) ကျပ်သားသည် တစ်နိက္ခဖြစ်၏။ (၄) နိက္ခသည် တစ်ပိဿာဖြစ်၏။” || “တၞဟ်နပူဇဴအ္စာဂှ် ဗောဓိသတ်ဂွံထဝ်ထပှ်နိက်တုဲ ပ္ဍဲမကၠောံဂၚ်ဂှ် ဍိုက်ဗက်ကၠောံဂၠုၚ်ညး။” (ဇ—၄၇၈။ အစွောံ။) = “ဘုရားလောင်းသည် ရွှေခုနစ်နိက္ခတို့ကိုရလျှင် ဆရာအားပေးအံ့ဟုကြံ၍ ဂင်္ဂါမြစ်ကိုကူးခြင်းငှာ လှေကိုစီး၏။” (ညောင်ကန်) || “သမ္ၚေဟ်ဂှ် — ဖေက်ဘဲကမၠတ်ဒမၠတုဲ ထဝ်ကၠံဏိက် ကေတ်ပတိတ်ဏာတုဲတိုပ်လဝ်ပ္ဍဲတိ။” (ဇ—၈၉။ အစွောံ။) = “ထိုသူကြွယ်သည် သူခိုးဓါးပြရန်ကိုကြောက်၍ နိက္ခတစ်ရာသောရွှေကို ယူထုတ်သွားပြီးလျှင် မြေ­မြှုပ်ထား၏။”')
,(7851,3,11,'(န) နိဂ္ဂဟိတ်။ သေးသေးတင်။ (‘အံ၊ င်္အံ၊ အုံ’ အသံများရအောင် ‘အ၊ အိ၊အု’ ထက်တွင်တင်သော အစက်အပြောက်။ (= ခၞံက္ဍိုပ်) (ပါဠိ—နိဂ္ဂဟိတ))',NULL)
,(7852,3,4,'နုတ်သည်။','“ပ္ဍဲစှ်ဂှ် နုက်ထောံပန်မ္ဂး သှ်ေတြဴရ။” = “တစ်ဆယ်တွင် လေးနုတ်လိုက်လျှင် ခြောက်ကြွင်းသည်။” || နုက်ပ္တိတ် = နုတ်ယူသည်။ နုတ်ထုတ်သည်။')
,(7853,3,4,'(ပြန်ပေးဆွဲခံရသောသူ၊ ကျွန်ဖြစ်နေသူစသည်) လွတ်မြောက်လာအောင် ငွေပေးရွေးနုတ်သည်။',NULL)
,(7854,3,4,'တပ်နုတ်သည်။ တပ်ရုပ်သည်။','“နုက်ပၞာန်ဇက်ကလေၚ်စဴရ။” (အကြီုရာဇာဓိရာဇ်) = “တပ်ရုပ်၍ပြန်၏။”')
,(7855,3,1,'ကြီးတော် (အမိ၏အစ်မ) ။ အရီး (အဖ၏အစ်မ) ။ မိကြီး။','သဳမူနော်တြ = မိထွေးဘထွေးမိကြီးဘကြီး အစရှိသောဆွေမျိုးအသိုင်းအဝိုင်း။ || “ဗမၞိဟ်ဗြဴဝွံဂှ် ဒှ်မိအဲမသုန်ကၠံဘဝ ဟွံဂွံသ္ဂုတ်၊ဒှ်သဳအဲမသုန်ကၠံဘဝ၊ ဒှ်နော်အဲမသုန်ကၠံဘဝရ။” ကျာ်တြဲဂး။ (ဇ—၆၈။ အစွောံ။) = “ထိုပုဏ္ဏေးမသည်လည်း မပြတ်လျှင် ဘဝငါးရာတို့ပတ်လုံး ငါ၏အမိဖြစ်ဘူးပြီ။ ဘဝငါးရာတို့ပတ်လုံး ငါ၏မိထွေးဖြစ်ဘူးပြီ။ ဘဝငါးရာတို့ပတ်လုံး ငါ၏မိကြီးဖြစ်ဘူးပြီ။” (ညောင်ကန်) || “ဗစဲပန်ဂှ် မိပိုဲမကဵုရောၚ်၊ ကောန်တြုံဒေံတြုံမကဵုရောၚ်၊ သဳမူပိုဲမကဵုရောၚ်၊ နော်တရပိုဲမကဵုရောၚ်၊ တွဵုကလောတံဂှ် ဒှ်တွဵုဒဒှ်ေဒယှ်ရောၚ်” ခမဳတံလ္ၚဵုဂး။ (ဇ—၉၃။ အစွောံ။) = “ပစ္စည်းလေးပါးကို ငါတို့မိခင်ပေး၏၊ ငါတို့သားငါတို့ညီပေး၏၊ ငါတို့အဒေါ်ဦးလေးပေး၏၊ ငါတို့မိကြီးဘကြီးပေး၏၊ ဆွေမျိုးတို့၏ပေးခြင်းသည် အကျွမ်းဝင်သဖြင့်ပေးခြင်းဖြစ်၏” ဟု အချို့သောရဟန်းတို့ဆိုကုန်၏။ (တရ= ဘကြီး။ ဦးရီး။) || “ဇၞော်ကော်ၝဲသၟတ်၊ သွတ်ကော်ဒေံကၠာ။ ကြိုက်သဳသဳကော်၊ ကြိုက်နော်ကော်အာ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “ကြီးသူကို အစ်မဟု၄င်း၊ ငယ်သူကို ညီမဟု၄င်း၊ ဒေါ်လေးဟုခေါ်သင့်သူကို ဒေါ်လေးဟု၄င်း၊ မိကြီးဟုခေါ်သင့်သူကို မိကြီးဟု၄င်း ခေါ်ဝေါ်ပါလော့။”')
,(7856,3,1,'လက်မောင်း။ (ကဝက်နော်တဲမ္ဂးဂှ် နူကဵုတၚ်တဲ စဵုကဵုမုဟ်ပၞးရ။','တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) || ‘ဂၞော်တဲ/ဂၞံက်တဲ’ ဟုလည်း အချို့ရေးသည်။')
,(7857,3,1,'ကြီးတော်။ အရီး။','“နော်နာဲတရဴ၊ ဟွံညာတ်တဴညိ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “အရီးခြောက်ယောက်တို့ကို မမြင်ရ။” || “နော်နာဲချပ်ဂြၚ်၊ ဗိုၚ်ရီုဗၚ်ညိ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ကြီးတော်စဉ်းစားဆင်ခြင်၍ ဝိုင်းကူပါလော့။” || ‘တြနာဲ’ (န) လည်းရှု။')
,(7858,3,4,'ယူလာသည်။ ဆောင်ခဲ့သည်။','“နၚ်ထးဂှ်ရ။” (ဇ—၃။ အစွောံ။) = “ထိုခွက်ကို ယူလာလော့။” || “နူရးသၟဝ်ကျာတေံ ညးကၠုၚ်ပဗၞိက်ချေံ ညးနၚ်ချေံမသုန်ကၠံ။” (ဇ—၁၅၈။ အစွောံ) = “မြောက်အရပ်တိုင်းမှ မြင်းအရောင်းအဝယ်ပြုရန် လာကြကုန်၏။ ငါးရာကုန်သောမြင်းတို့ကိုဆောင်ခဲ့ကုန်၏။”')
,(7859,3,1,'ခုတၚ်။ ခုလေးတၚ်။','“ယွံညးမပ၊ တၠပါၚ်ပြဟ်။ — နၚ်ကၠၚ်ဂးသှ်၊ လၟုဟ်သ္ၚိတ်အာ။” (လိက်ဘောဂရေန်) = “အို—နှုတ်မြန်သောသူ၊ ခုလေးတင်ဖြေကြားမည်ဆိုပြီး ယခုနှုတ်ဆိတ်သွားလေပြီ။”')
,(7860,3,1,'နန်းတွင်းသူ။ မောင်းမ။','“ကမၠောန်နၚ်စၚ်ကီု ညးဍုၚ်ဂမၠိုၚ်ကီု မသက်ကဵုယဲဒှ်ညိဟာ။” (ဇ—တေမဳ။ အစွောံ။) = “မင်းမောင်းမနန်းတွင်းသူတို့သည်၄င်း ပြည်သူတို့သည်၄င်း အနာရောဂါကင်းသည်ဖြစ်ပါကုန်၏လော။” || “ဗြဴဂှ်ဇၞော်ပြဲ တိုန်ဒှ်နၚ်စၚ် ဝၚ်ဨကရာဇ်။” (လောကသိဒ္ဓိ။ အစွောံ။) = “ထိုမိန်းမသည် ကြီးမြတ်၍ ဘုရင့်နန်းတော်­ နန်းတွင်းသူတက်ဖြစ်၏။”')
,(7861,3,4,'အပြစ်ရှာသည်။ အပြစ်ဖို့သည်။ စွပ်စွဲသည်။',NULL)
,(7862,3,4,'အရောက်ယူဆောင်လာသည်။','“ဟာဲကၠ၊ ပ္ဍဲကၠာတေံဂှ် — ဖျုန်ကၠိက်ပြဲပြဲခိုဟ်ဟ်ဂှ်မနၚ်ဗစိုပ်အဲ။ ပ္ဍဲတ္ၚဲဝွံဂှ် ဗှ်ေစဴကၠုၚ်တဲသၟး—” ရသိစၞာဲဂး။ (ဇ—၂၈၃။ အစွောံ။) = “ဟယ်ကျား၊ယခင်အခါ­ သင်သည် မြတ်သောကောင်းသောဝက်သားကို ငါ့အတွက် အရောက်ယူဆောင်လာ၏။ ဤယနေ့­မူ သင်သည် လက်ချည်းဗလာပြန်လာ၏” ဟုရသေ့စဉ်းလဲဆို၏။ || “ဂဒိုအ်မွဲ မနၚ်ဗစိုပ်ညးသြၚ်လ္ပာ်တေံဂှ်—။” (ဇ—၃၇၆။ အစွောံ။) = “ထိုမှာဘက်ကမ်းသို့ သူတစ်ပါးကို ပို့ဆောင်လာသော တစ်ယောက်သောကူးတို့သမား—။”')
,(7863,3,4,'မိမိပျက်စီးရာပျက်စီးကြောင်း သူတစ်ပါးတို့ကြံစည်ပြုလုပ်သည်။','“ညံၚ်ဍေံနၚ်လေၚ်ကဵုအဲဂှ် လလေၚ်ဂှ် ကဵုစိုပ်ဍေံညိ။” (အကြီုရာဇာဓိရာဇ်) = “ငါပျက်စီးရာပျက်စီးကြောင်းကို သူကြံစည်ပြုလုပ်သကဲ့သို့ ပျက်စီးခြင်းသည် သူ့ဆီရောက်ပါစေသတည်း။”')
,(7864,3,4,'မိမိပျက်စီးရာပျက်စီးကြောင်းကို သူတစ်ပါးတို့မကောင်းကြံစည်ပြုလုပ်သည်။ မိမိ၏အကျိုးမဲ့ကို (သူတစ်ပါးတို့) ပြုလုပ်သည်။','“ယွံအမာတ်၊ ညးနၚ်အမှုလေၚ်ကဵုအမာတ်တုဲ အမာတ်ဂွံတသိုက်ဂှ် ဆလၟုဟ်ဒှ်ဟွံသေၚ်။ ပ္ဍဲကာလမတုဲတေံလေဝ် ညးနၚ်အမှုလလေၚ်ကဵုတၠပညာတံတုဲ တၠပညာတံ ဂွံတသိုက်ကီုတုဲရ။” (ဇ—၂၈၂။ အစွောံ။) = “အမတ်၊ သင်သည်သာလျှင် သူတစ်ပါးတို့ မိမိအားအကျိုးမဲ့ကိုပြု၍ ချမ်းသာကိုရသည်မဟုတ်။ ရှေးပညာရှိတို့သည်လည်း သူတစ်ပါးတို့ မိမိအားအကျိုးမဲ့ကိုပြု၍ ချမ်းသာကိုရဖူးကုန်၏။” || ‘နၚ်လေၚ်’ နှင့်အတူတူ။')
,(7865,3,1,'ကျပ်ခိုးစၚ်။','“ပ္ဍဲဂြောန်၊ ပ္ဍဲနာၚ်၊ ပ္ဍဲတရၚ်၊ ပ္ဍဲဓမၚ်သ္ၚိတံဂှ်။” (ဇ—ဘူရိဒတ်။ အစွောံ) = “ပစ္စည်းတင်ရန်စင်­၄င်း၊ ကျပ်ခိုးစင်­၄င်း၊ တံခါး­၄င်း၊ အိမ်ထုပ်လျောက်တို့­၄င်း။”')
,(7866,3,9,'အရေအတွက်၊ ပမာဏကို မှန်းဆပြောဆိုရာတွင် သုံးသောစကားလုံး။ လောက်။မျှ။','လ္ၚီနာၚ် = တစ်ထောင်လောက်။ || “ယွံမၞးတံ၊ မတ်ဗြဲမ္ဂးဝွံ မူစိဗၞတ်ဋ္ဌာန်ဇမ္ၚောဲ မၞးတံမညာတ်ရော” ဗောဓိသတ်သၟာန်၊ “ယွံနာဲပိုဲ၊ ဗၞတ်ပိယောဇနာနာၚ် မဂွံညာတ်ရအဴ” ညးဂမၠိုၚ်ဂး။ (ဇ—၁။ အစွောံ။) = “အချင်းတို့၊ မိုးတိမ်ညွန့်မည်သည်ကား အဘယ်မျှလောက်သောအရပ်­ထင်သနည်း” မေး၏၊ “အရှင်၊ သုံးယူဇနာမျှလောက်သောအရပ်­ ထင်၏” ဟုဆိုကုန်၏။ (ညောင်ကန်) || ‘သမာလှ်ေမၞုံတြဴလ္ၚီနာၚ်။’ (ဇ—၄၈၉။ အစွောံ။) = ‘ခြောက်ထောင်မျှသောကချေသည်များ။’ || “ပ္ဍဲသ္ၚိပိုဲဍိက် ဒြပ်ဒစာံစှ်ောကိုတ်နာၚ်နွံ။” (ဇ—၇၈။ အစွောံ။) = “အကျွန်ုပ်အိမ်­ ကုဋေရှစ်ဆယ်မျှသောဥစ္စာရှိ၏။” || “အၚပ်တဟၚ်အဲ နွံမွဲနာၚ်။” (ဇ—၇၈။ အစွောံ။) = “ငါ့မှာ တစ်ခုမျှသောချင်ခြင်းရှိ၏။”')
,(7867,3,1,'ထင်းရူးပင်။',NULL)
,(7868,3,1,'ဓါး။ ဆံရိတ်ဓါး။','ၜုန်နိၚ် = သင်ဓုန်းဓါး။')
,(7869,3,1,'အိုး။',NULL)
,(7870,3,1,'ဖျဉ်းအိုး။ (အဝကျယ်သော ရေအိုးတစ်မျိုး။) (ပါဠိ—ကုဏ္ဍက)',NULL)
,(7871,3,1,'ပန်းအိုး။ ရေအိုး။','“ကဵုတုက်ဍာ်ကၠာ၊ ကမာဒကှ်။ ဗြဴဣလုဂှ်၊ လေၚ်နုၚ်ကၠဟ်ထဝ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ပဒုမ္မာကြာရေကန်­ ရေခပ်စေ၍ မိလုမည်သောမိန်းမသည်ရွှေရေအိုးကို ခါးထစ်တွင်တင်ထား၏။”')
,(7872,3,1,'ရေခပ်သောအိုး။',NULL)
,(7873,3,1,'မြို့ရိုးပေါ်ရှိပြအိုး။',NULL)
,(7874,3,1,'ဖျဉ်းအိုး။ (ပါဠိ—ကုဏ္ဍ)',NULL)
,(7875,3,1,'ညောင်ရေအိုး။',NULL)
,(7876,3,1,'သောက်ရေအိုး။',NULL)
,(7877,3,1,'အတာအိုး။',NULL)
,(7878,3,1,'ပန်းအိုး။ ညောင်ရေအိုး။','“သော်ညံၚ်သၞေၚ်ထိုၚ်၊ ဒၞေၚ်မတ်ဝိုၚ်သောၚ်။ ကအ်ခဏာၚ်သၠုၚ်၊ နုၚ်အဖၠူရောၚ်။” (လိက်သောဝါနနဟောၚ်) = “ပိတုန်းရောင်ကေသာနှင့်ကော့ဝိုင်းသောမျက်တောင်ရှိပြီး ညောင်ရေအိုးကဲ့သို့ မြင့်သေးသွယ်သောလည်တံရှိ၏။”')
,(7879,3,1,'ဆူးတောင်။ ချိတ်။ အထစ်။','နေၚ်က = ငါးဆူးတောင်။ || နေၚ်ခၞောန် = ငါးမျှားချိတ်။')
,(7880,3,1,'၁။ တံစဉ်။',NULL)
,(7880,3,1,'၂။ ကညွတ်ပင်။',NULL)
,(7880,3,4,'ကျပ်ထုပ်ထိုးသည်။',NULL)
,(7881,3,10,'(ကြိ) မရှိ။ နတ္ထိ။',NULL)
,(7882,3,10,'(န) အမြဲ။ နိစ္စ။',NULL)
,(7883,3,10,'(ကြိဝိ) အမြဲတမ်း။ အမြဲမပြတ်။ အခါခပ်သိမ်း။','“(ခမဳဂှ်) ဍိုက်ပေၚ်တဴကဵုဝတ်ပဋိပတ် — (ဝတ်ဂၠိုၚ်သာ်တံဂှ်) နိစ္စကာလ ပ္တုဲတဴဟွံပိုတ်ရ။” (ဇ—၁၂၄။ အစွောံ။) = “ထိုရဟန်းသည် ဝတ္တရားနှင့်ပြည့်စုံ၏။ များစွာသောဝတ္တရားတို့ အခါခပ်သိမ်း အမြဲမပြတ်ပြု၏။”')
,(7884,3,10,'(ကြိဝိ) အမြဲမပြတ်။ ထာဝစဉ်။ နိစ္စဓူဝ။',NULL)
,(7885,3,11,'(န) အမြဲမပြတ်လှူသောဆွမ်း။ နိစ္စဘတ်ဆွမ်း။',NULL)
,(7886,3,10,'(န) အမြဲစောင့်ထိန်းအပ်သောသီလ။ နိစ္စသီလ။',NULL)
,(7887,3,10,'(န) ၁။ နိဿယ။ ပါဋ္ဌ်တစ်ပိုဒ် အနက်တစ်ပိုဒ် ပြန်ဆိုထားသော ဘာသာပြန်။',NULL)
,(7887,3,10,'(န) ၂။မှီးငြမ်းပြုရာနည်းနာ။ နိဿယ။',NULL)
,(7888,3,11,'(ကြိ) မှီသည်။ မှီခိုသည်။ အမှီပြုသည်။ (ပါဠိ—နိဿယ)','“ကွာန်ပစ္စန္တရးမွဲနွံ (ဣသိဂှ်) နိဿဲကဵုကွာန်ဂှ်တုဲ ခၞံအဿမာပိုတ်တုဲ ဒၟံၚ်တဴရ။” (ဇ—၂၇၇။ အစွောံ။) = “ထိုရသေ့သည် တခုသောပစ္စန္တရစ်ရွာကိုမှီ၍ ကျောင်းဆောက်၍ နေ၏။” || “ပ္ဍဲဂြိုပ်ဂှ် လစဇၞော်မွဲနွံ။နိဿဲကဵုလစတုဲ ကၠိက်ဂမၠိုၚ်နွံ။” (ဇ—၁၅၃။ အစွောံ။) = “ထိုတော­ တခုသောအိုင်ကြီးသည်ရှိ၏။ ထိုအိုင်ကိုမှီကုန်၍ များစွာကုန်သောဝက်တို့သည် နေကုန်၏။” || “နိဿဲဒးကဵုတၠပညာတုဲ မဂွံလမျီုရောၚ်သွံ။” (ဇ—၃၈၆။ အစွောံ။) = “ပညာရှိကိုမှီ၍ အသက်ကိုရ၏။” || “(ကၠဵုဂြိုပ်ဂှ်) နိဿဲကဵုမာနဂှ်တုဲ အာစိုပ်လေၚ်ဟေၚ်ရ။” (ဇ—၃၃၅။ အစွောံ။) = “ထိုမြေခွေးသည် မာနကိုမှီ၍ (မာနကြောင့်) ပျက်စီးခြင်းသို့ရောက်ရ၏။” || “ဣသိဇာတိမန္တဂှ် နိသြဲကဵုဇာတိဂကူတုဲယိုက်ဇၞောဝ်မာန် သလုၚ်မာနလောန်။” (ဇ—၄၉၇။ အစွောံ။) = “ဇာတိမန္တရသေ့သည် အမျိုးဇာတိကိုမှီ၍ မာနတံခွန်ထူလျက် အလွန်ထောင်လွှားမောက်မာ၏။”')
,(7889,3,16,'(န) ပူဆွေးသောက။ သောကမီး။','“ကောအိုတ်ခန္ဓ၊ဒေါဝ်ရညဝါ။ ဟွံတီသၞေဟ်သြၚ်၊ မိဒးကြၚ်အာ။ ဟွံတီဒိုဟ်ကၠၚ်၊ ဗဵုနိတ်သၚ်ဟာ။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “မယ့်ချစ်သူမောင်သည် တောကြီးလယ်­ သေဆုံး၏။ မယ့်ခမျာခိုကိုးရာမရဖြစ်ကာ အရပ်မျက်နှာကိုမမှတ်မိဘဲ တောကြီး­ လှည့်လည်သွားလာနေရပါ၏။ မယ့်သောကအပူမီးကို မောင်မြင်ချင်၍လော။” || “မိကဵုကောန်ဍောတ်၊ ဍာ်ရမတ်ဇွောဝ်။ နိဿၚ်ကာဲကဝ်၊မၞးဗဵုဒ္ၚောဝ်ရော။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “မိခင်နှင့်သားငယ်တို့သည် ပူဆွေး၍မျက်ရည်ယို၏။ သောကအပူမီးလွန်ကဲသည်ကို အဘယ်ကြောင့် သၚ်ကြည့်နေနိုင်ရက်သနည်း။” || “ပဟွံချပ်ဂြၚ်၊ ကဵုဒေံဇွောဝ်လၚ်၊ ဗဵုနိတ်သြၚ်ရော။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “အဘယ့်ကြောင့်မတွေးမြင်ဘဲ ညီတော်ဝမ်းနည်းကြေကွဲနေရသော သောကအပူမီးကို ကြည့်ရက်လေသနည်း။”')
,(7890,3,11,'(န) ‘နိဿန္ဒ’ နှင့်အတူတူ။',NULL)
,(7891,3,10,'(န) အကျိုး။ အကျိုးဆက်။','“ဗြဴသုဓမ္မာမွဲဂှ် ဖဵုနိဿန္ဒမကဵုဒါန်ဓုပ်ပြကာဂှ် စုတိတိုန်က္တဵုဒှ်ဂၞကျာ်သၟိၚ်အိန်။” (ဇ—၃၁။ အစွောံ။) = “သုဓမ္မာအမျိုးသမီးသည် ထုပိကာကို လှူသောအကျိုးဆက်ကြောင့် စုတေလတ်သော် သိကြားမင်း၏မိဖုရားဖြစ်လာ၏။” || “ဖဵုနိဿန္ဒအဲမကဵုလဝ်ဒါန်ဂှ် (ပ္ဍဲဒေါဝ်မှာသၟိတ်) အဲကလိဂွံသၞေဟ်သၚ်တုဲရ။” (ဇ—၄၄၂။ အစွောံ။) = “ငါပေးအပ်သောအလှူဒါန၏အကျိုးဆက်ကြောင့် မဟာသမုဒ္ဒရာလယ်­ ငါသည် တည်ရာကိုရဖူးပြီ။”')
,(7892,3,1,'‘နတ်’ ရှု။',NULL)
,(7893,3,1,'နန်း။ နန်းတော်။','နန်မြ = မြနန်း။ || တိုန်နန် = နန်းတက်သည်။ || တၠနန်ထဝ် = ရွှေနန်းရှင်။')
,(7894,3,1,'နန်းအိမ်။ နန်းပြာသာဒ်။','“ကောန်သမ္ဘာသဟာဲဂှ် (သၟိၚ်) ကဵုညးအာဒုၚ်နၚ်တုဲ ပ္ဍဲဒေါဝ်ဍုၚ်ဂှ် က္တဵုဗဒှ်ကဵုနန်ကၠတ်သ္ၚိကၠတ်တုဲ ဇိုန်ကဵုရ။” (ဇ—၃ဝ၂။ အစွောံ။) = “မင်းသည် အဆွေခင်ပွန်း၏သားမယားတို့ကို ခေါ်ဆောင်လာစေ၍ မြို့လယ်­ နန်းပြာသာဒ်နန်းအိမ်ကို ဆောက်လုပ်စေပြီးလျှင် ပေး၏။” || “တာန်ဆံၚ်နန်ကၠတ်၊ သ္ၚိရတ်အိန်သ္ဂီု။” (လိက်ပဒုမဝတဳ) = “တန်ဆောင်း၊ နန်းပြာသာဒ်နှင့် ရတနာအိမ်နန်းတို့သည် တင့်တယ်ကုန်၏။” || ‘ကၠတ်’ (န) လည်းရှု။')
,(7895,3,1,'ဘုရင့်နန်းတော်။',NULL)
,(7896,3,1,'နန်းတော်။','“လတူဒဳသၟိၚ်၊ သမၞိၚ်နန်ဂွိုၚ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်) =“နန်းတော်ရိပ်မြုံ မင်း၏ပေါင်ပေါ်­။”')
,(7897,3,4,'‘ဂၞန်တး’ ရှု။',NULL)
,(7898,3,11,'(န) နန္ဒမူလိုဏ်။ (ကျမ်းဂန်လာ အနောတတ်အိုၚ်ကို ရံလျက်ရှိသောတောင်ငါးလုံးအနက် ဂန္ဓမာဒနတောင်ခြေရင်းရှိ ပစ္စေကဗုဒ္ဓာတို့ သီတင်းသုံးတော်မူရာဂူလိုဏ်။)',NULL)
,(7899,3,1,'တစ်ပင်တိုၚ်နန်း။','“ဗွဲမပြဟ်ဟေၚ် စဳရေၚ်နန်ဒယိုင်မွဲ တုဲအာဗွဲမပြဟ်ရ။” (သၠပတ်သုရသာ) = “အလျင်အမြန် တစ်ပင်တိုင်နန်းကိုစီရင်၍ အလျင်အမြန်ပြီးစီးသွား၏။”')
,(7900,3,1,'နန်းတော်။','“ကောံသၟိၚ်မပြဲ၊ မံၚ်ပ္ဍဲနန်ဒြၚ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) =“မြတ်သောမင်းနှင့်အတူတကွ နန်းတော်­နေ၏။”')
,(7901,3,1,'နန်းတော်။ မြနန်း။','“နွံတဴဟွံေၚာဲ၊ အပ္ဍဲနန်မြ။ ဂကောံသၟိၚ်မ၊ ဋ္ဌာနထာန်နန်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ခမည်းတော်မင်းကြီးနှင့်အတူ နန်းရပ်ဋ္ဌာန မဝေးသောမြနန်း­ ရှိပါ၏။”')
,(7902,3,1,'နန်းတော်။','“ယွံအံက်သၟိၚ်မ၊ တလနန်ယာန်။” (ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “နန်းတော်ပိုင်ရှင် အို—ခမည်းတော်မင်း။”')
,(7903,3,1,'နန်းတော်။','“ယွံနာဲနန်လွိ၊ တလတိဒှ်။” (လိက်ကောန်ဂစေံပိ။ နာဲဗျူ။) = “အို—ရွှေနန်းရှင် ရေမြေ့ရှင်—။”')
,(7904,3,4,'သီချုပ်သည်။ ဖာချုပ်သည်။','“ပလောအ်ထောၚ်စာ်ဒၟံၚ်ဂှ် နာပ်ကဵုမွဲတဲညိ။” = “စုတ်ပြဲနေသောအင်းကျီကို တဆိတ်လောက်ဖာချုပ်ပေးပါ။”')
,(7905,3,4,'ဖာထေးသည်။',NULL)
,(7906,3,11,'(န) နိဗ္ဗာန်။',NULL)
,(7907,3,1,'ကျက်တဟင်းရွက်ပင်။',NULL)
,(7908,3,11,'(န) ၁။ နာမ်။ (ခံစား၊ မှတ်သား၊ ပြုပြင်၊ သိမြင်တတ်သောတရား။)','ရုပ်နာမ် = ရုပ်နာမ်နှစ်ပါး။')
,(7908,3,11,'(န) ၂။ (သဒ္ဒါ) နာမ်။ သက်ရှိသက်မဲ့၊ ဒြပ်ရှိဒြပ်မဲ့တို့၏အမည်။',NULL)
,(7909,3,1,'အစေးမှလာသော အမွှေးနံ့သာတစ်မျိုး။',NULL)
,(7910,3,1,'ရေပုံး။',NULL)
,(7911,3,1,'အင်းအိုင်။ ချောင်း။ (?)','“တြိယောဇနာန်မဇက်ကၠုၚ်ဂှ် —— ဇၟာပ်ၜဳဇၟာပ်ပၞုၚ်နာံထံၚ်မဂၠာဲဒမံၚ်သတြုကီု။” (အာန်ဇုနာန်) = “တြိယောဇနာန်ချီလာပြီး —— ပင်လယ်ရေကန်အင်းအိုင်တိုင်း­ ရန်သူ့တည်နေရာကို ရှာနေသကဲ့သို့။” || “ဂရော်နာံထံၚ်၊ ဒၞာဲခဏံၚ်ကၠာ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “လျှိုမြောင်အင်းအိုင် ဝဲဂယက်ရှိသောနေရာ­။”')
,(7912,3,16,'(န) ၚံပြာရည်။','“ဝးကအ်သုၚ်ဆီ၊ ဗှ်ေဟွံတီဟာ။ ဖျုန်ဗှ်ေစုတ်မြေက်၊ပေက်ကဵုနာံပၠာ။” (လိက်သောဝါနနဟောၚ်) = “(ငါကား) နင့်လည်ကိုချိုး၍ နင့်သွေးကိုသောက်မည်ကို နၚ်မသိသလော။ နင့်အသားကို ငရုတ်သီးထည့်ကာ ၚံပြာရည်နှင့်သုပ်စားမည်။”')
,(7913,3,4,'၁။ အလေးအမြတ်ပြုသည်။ အဓိကထားသည်။','“ယြဴတြုံမွဲ — တီဂုန်ခမဳဗမၞးဇၞော်ကၠးပ္ဍဲဓဝ်သဳလ မဖေက်ပါပ်မဂွပါပ် မလေပ်နာံဗျာပ်ပ္ဍဲဒါန်သဳလဘာဝနာ—။” (ဇ—နာရဒ။ အစွောံ။) = “အကြင်ယောကျာ်းသည် ရဟန်းပုဏ္ဏားတို့၏ ဂုဏ်ကျေးဇူးကိုသိ၏။ သီလတရား­ကြီးမြတ်၏။ အရှက်အကြောက်ရှိ၏။ ဒါန၊ သီလ၊ ဘာဝနာ­ အလေးအမြတ်ပြုတတ်၏။” || “ဂွံမိၚ်ဓမ္မဒေသနာ ဇရေၚ်တံဇိုၚ်ကျာ်တြဲတုဲ ကဵုကလိဂွံအဘိညာဏ်တြဴ သမာပတ်ဒစာံ နာံဗျာပ်လဝ်ဓဝ်လောကုတ္တဵုဒစိတ်ပြကာ။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “မြတ်စွာဘုရားခြေတော်ရင်း­ ဓမ္မဒေသနာကို နာကြားရပြီးနောက် အဘိညာဉ်ခြောက်ပါး သမာပတ်ရှစ်ပါးတို့ကိုရရှိပြီး ကိုးပါးသောလောကုတ္တရာတရားကို အလေးအမြတ်ပြုထား၏။” || “ဝုတ်ဗၠာဲထဴဗျု၊ ဇၟာပ်ပုထုဇန်။ ကုသိုလ်နာံဗျာပ်၊ သ္ဂောံပ္တုဲဇၟာပ်တန်။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “ပျိုပျိုအိုအို ပုထုဇဉ်တိုင်းသည် ကုသိုလ်တရားကို အလေးအမြတ်ထား၍ ကုသိုလ်မှုတိုင်းကို ပြုကြလျှင်—။” || “ခမှဳဗၞး၊ညးနွံပညာ။ ညးနွံသဳလ၊ စာဂသဒ္ဓါ။ — ထာန်ဇကုသၟတ်၊ ကဵုစိုပ်ဆတ္တဝ်။ စိုပ်တုဲနာံဗျာပ်၊ ဗစဖာပ်လဝ်။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “ပညာ၊ သီလ၊ စာဂ၊ သဒ္ဓါတရားတို့နှင့်ပြည့်စုံသော ရဟန်းပုဏ္ဏားတို့က မိမိနေရာအရပ်သို့ ရောက်လာသည်ရှိသော် အလေးအမြတ်ပြု၍ကျွေးမွေးထားမည်။”')
,(7913,3,4,'၂။ ထူးချွန်လိမ္မာသည်။ ကျွမ်းကျင်လိမ္မာသည်။ လိမ္မာပါးနပ်စွာပြောဆိုသည်။','“(ဗောဓိသတ်) မပတၠပညာ မသာဓါနာံဗျာပ်အာ ဇၟာပ်ကွတ်စှ်ဒစာံသာ်။” (ဇ—ဝိဓုရ။ အစွောံ။) = “ဘုရားလောင်းသည် တစ်ဆယ့်ရှစ်ရပ်သောအတတ်တို့­ စွမ်း၍ထူးချွန်လိမ္မာသောပညာရှိဖြစ်၏။” || “ကွတ်စှ်ဒစာံ၊ နာံဗျာပ်လေပ်ဟေၚ်။” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။) =“တဆဲ့ရှစ်ရပ်သောအတတ်တို့ကို ကျွမ်းကျင်ထူးချွန်တတ်မြောက်၏။” || “ကွတ်စှ်ဒစာံ၊ နာံဗျာပ်ကၠောံသ္ဍ။ ဇၟာပ်ကွတ်လေပ်ဇဳ၊ ပညာစဳခၠ။” (လိက်ပဒုမဝတဳ) || “ဣထဳရာဇာတုန်လေ သ္ဒးအာဟီုအရေဝ် မဒးစကာကလုတ်တမာန်တုဲ ကဵုတိတ်နာံဗျာပ်တဴကဵုသၟိၚ်ပန်ရ။ သီုသၟိၚ်ပန်စိုတ်ဍိုန်အာတုဲ—။” (ပြကိုဟ်ဂဝမ္ပတိ) = “ဘုရင်မကြီးသည် စကားပြောဆိုရန်ရှိ၍ သံတမန်တို့ကိုစေလွှတ်၍မင်းလေးပါးတို့အား လိမ္မာပါးနပ်စွာပြောဆိုစေ၏။ မင်းလေးပါးစလုံး စိတ်ပျော့ပျောင်းသွားကုန်၏။”')
,(7914,3,4,'ထွန်းပသည်။ (?)','“သၟတ်ဗြဴမွဲ ညံၚ်ရုပ်ထဝ်အာန်ဇနဳကီု ညံၚ်အရံၚ်မၞိက် မနာံဗျာံဒၟံၚ်အလုံဇကု။” (အာန်ဇုနာန်) = “မိန်းမငယ်တစ်ယောက်သည် ရွှေစင်ရုပ်ကဲ့သို့ဖြစ်၍ ပတ္တမြားအဆင်းကဲ့သို့ တစ်ကိုယ်လုံးထွန်းပနေ၏။”')
,(7915,3,1,'မိတ်ဆွေ။ အဖော်သဟဲ။','“ကောန်အမာတ် (၅ဝဝ) သၟိၚ်ကဵုပနာံမြိုင်ဗောဓိသတ်ရ။” (ဇ—တေမဳ။ အစွောံ။) = “မင်းသည် (၅ဝဝ) ကုန်သော အမတ်တို့၏သားတို့ကို ဘုရားလောင်း၏ အဖော်သဟဲပြုစေ၏။” || “(သၟိၚ်ဂမၠိုၚ်) ပဂကောံနာံမြိုင် တွဳဗွိုၚ်ကေတ်ဣသိနန္ဒတုဲ—။” (ဇ—၅၃၂။ အစွောံ။) = “မင်းအပေါင်းတို့သည် နန္ဒရသေ့ကို အဖော်ပြုခြံရံကုန်၏။” || “ပနာံမရိုၚ်ကဵုဓဝ်သဒ္ဓာ။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “သဒ္ဓာတရားကို အဖော်သဟဲပြု၏။” || “ပနာံမြိုင်ကဵုပညာ။” (ပြကိုဟ်မ္ငိုလ်ပိစှ်ောဒစာံ) = “ပညာကို အဖော်ပြုသည်။” || “ကလောဂမၠိုၚ်ဂှ် ဟိုတ်မဒှ်နာံမြိုင် နိတ်သြဲကေုာံရၚ်သ္ကံ—။” (သၠပတ်ကုလဇာတ်) = “ဆွေမျိုးတို့သည်အဖော်သဟဲဖြစ်ခြင်းကြောင့် အချင်းချင်းအမှီပြုကြကုန်၏။”')
,(7916,3,1,'အဖော်။ အဖော်အဖက်။','“ၝဲတရဴပၠန်၊ ဇြဟာန်အန်အာ။ ဟွံၚဳကိစ္စ၊ ဟွံပနာံသာ။ကောံဒေံဍောတ်ရ၊ ခယသာဓါ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “အစ်မခြောက်ယောက်တို့သည် ချစ်ခြင်းနည်းသွားသည်ဖြစ်၍ ညီမငယ်အား မကြည့်မနှစ်မြို့ အဖက်မလုပ်ကြကုန်။” || “ညးသ္ဂောံဖေက်ဂွ၊ သ္ဂောံပနာံသာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “သူတစ်ပါးတို့ရှက်ကြောက်လေးစား အဖော်အဖက်ပြုကြရန်။” || “သဳနော်ဗဴလ၊ သ္ဂောံပနာံသာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ထွေးတော်၊ မိကြီး၊ အဘွား၊ အဘိုးတို့ အဖော်ပြုရန်။”')
,(7916,3,4,'ကျီစယ်သည်။','“တြုံဗောဓိသတ်၊ မထတ်ပညာ။ ကောံဗြဴၜါကျဝ်၊ သၟဝ်က္ဍိုၚ်ထာၚ်သွာ။ —လဗိၚ်သဍံက်၊ စံက်ထေအ်နာံသာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ပညာထက်သောဘုရားလောင်းသည် မိန်းမနှစ်ယောက်နှင့်အတူ ထီးဖြူတော်အောက်­ မွေ့လျော်ရွှင်ပျော် ကစားကျီစယ်၏။”')
,(7917,3,1,'အခြံအရံ။','“ကေုာံအမာတ်တြဴစှ်ောလ္ၚီ ပနာံသေတ်သတုံဇွိကြဴဂတ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ခြောက်သောင်းကုန်သောအမတ်တို့ကို ဝဲယာရှေ့နောက် အခြံအရံပြု၍—။”')
,(7918,3,11,'(န) ၁။ အကြီးအမှူး။ ခေါင်းဆောင်။','နာဲဂၠုၚ် = လှေသူကြီး။ || နာဲက္ၜၚ် =သင်္ဘောသူကြီး။ || နာဲသာဗၞိက် = ကုန်သည်အကြီးအမှူး။ || နာဲညးပိစှ်ောမွဲဘုံ = သုံးဆဲ့တစ်ဘုံ၏အကြီးအမှူး။ မြတ်စွာဘုရား။')
,(7918,3,11,'(န) ၂။ အရှင်သခင်။','နာဲကဵုဍိက် = သခင်နှင့်ကျွန်။')
,(7918,3,11,'(န) ၃။ ရဟန်းလူထွက်ပြီးနောက် အမည်ရှေ့တွင်ထည့်ခေါ်သောစကားလုံံး။ လေးစားသည့်အနေဖြင့် ယောကျာ်းအမည်ရှေ့တွင် ထည့်သုံးသည့်စကားလုံး။ ဦး။ နိုင်။','နာဲထဝ် = နိုင်ထော။ ဦးထော။')
,(7918,3,11,'(န) (နစ) သင်။ (များသောအားဖြင့် ရွယ်တူယောကျာ်းကို လေးစားသဖြင့်ခေါ်သော နာသူနာမ်စား ဖြစ်သည်။ မိန်းမကိုလည်း ရည်ညွှန်းခေါ်ဆိုနိုင်သည်။)','“ယွံနာဲထဝ်၊ နာဲဂွံအယုက်မူစိရရော။”= “နိုင်ထော်၊ သင်အသက်ဘယ်လောက်ရှိပြီလဲ။” || “ယွံစဴဗြဴ၊ — နာဲလ္ပယာံဗုတ်စဝ်ကဵုလဇုရ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ချစ်မြေးမလေး၊ အဘိုးကို သင်ငို၍မပူဆာပါလေနှင့်။”')
,(7919,3,1,'၁။ အကြီးအကဲ။ အကြီးအမှူး။ အထက်လူကြီး။ အထက်အရာရှိ။','‘ခစနာဲစာ’ =‘အကြီးအကဲကို ခစားသည်။’ || “အမာတ်တံဂှ်၊ သၟဟ်ဒဴဗညာ။ သကိုပ်ပၞာန်တံ၊ အိုတ်တၟံနာဲစာ။”= “အမတ်တို့သည်၄င်း၊ ဒေါဗညားတို့သည်၄င်း၊ စစ်ဦးစီးတို့သည်၄င်း၊ အစရှိသည့် အားလုံးသောအရာရှိကြီးများ။” || “နာဲစာပအမှု၊ ဇကုဒးစ္ဍးဋ္ဌာန်။” (လောကသိဒ္ဓိ။ အစွောံ။) = “မိမိ၏အထက်အရာရှိက မိမိအားအပြစ်လုပ်၍ မိမိ၏နေရာဋ္ဌာနကို စွန့်ခွာရသည်။” || “ကွာန်ဇၞော်မွဲရ၊မဒှ်ရးဗ္ၚ။ အဲဇိုန်ကဵုရ၊ ကဵုပနာဲစာ။ ကဵုကံက်စပၠန်၊ အခေါန်ဖလာ” (သၟိၚ်ဂး။) (လိက်မိဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “လယ်ယာစိုက်ရာအရပ်ဖြစ်သော ရွာကြီးတစ်ရွာကို ငါပေးမည်။ ထိုရွာ၏အကြီးအကဲလုပ်စေ၍ အခွန်ကောက်စားစေမည်” (ဟုမင်းဆို၏။)')
,(7919,3,1,'၂။ တရားဆုံးဖြတ်သူ။ တရားသူကြီး။','‘သၟိၚ်စာ’ ဟူ၍လည်းသုံး၏။ || ‘ရုၚ်စာ’ (န) လည်းရှု။')
,(7920,3,1,'ချစ်လှစွာသောသခင်။ (ချစ်သူရည်းစားကို တင်စားခေါ်ဝေါ်သော များသောအားဖြင့် ကဗျာသုံးစကားဖြစ်သည်။)','‘ဇု’ တွင်ရှု။')
,(7921,3,1,'လောကသုံးပါး၏အရှင်။ ဗုဒ္ဓမြတ်ဘုရား။',NULL)
,(7922,3,1,'ဘဏ္ဍာစိုး။','“ဒဒှ်နာဲတိုက်ထဝ် ပ္တန်လဝ်ညိရအဴ” အမာတ်တံဂး။ (ဇ—၅၂၁။ အစွောံ။) = “ဘဏ္ဍာစိုးအဖြစ် ခန့်ထားတော်မူပါလော့။”')
,(7923,3,1,'ထောင်မှူး။',NULL)
,(7924,3,1,'တမ်မှူး။','“တၠညးနွံအသံ ကဵုအာကော်သၟိၚ်ဗြာဇ္ဇ သီုကဵုသၟိၚ်ဗိုလ်စက္ကာဲနာဲဒပ်တံဂမၠိုၚ်။” (အကြီုရာဇာဓိရာဇ်) = “သမိန်ဗြာဇ္ဇနှင့်တကွ ဗိုလ်မင်းစစ်ကဲတပ်မှူးအပေါင်းတို့ကို သွားခေါ်ရန်ဘုရင်အမိန့်ရှိ၏။”')
,(7925,3,1,'လှေသင်္ဘောပဲ့သူကြီး။ ပဲ့နင်း။','“နာဲနာတ်ထောံက္ဍၚ်၊ သၞေဝ်က္ၜၚ်မူလ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ပဲ့သူကြီးသည် မူလသင်္ဘော၏ပဲ့ကို စွန့်ခွာသွား၏။”')
,(7926,3,16,'သင်။ (များသောအားဖြင့် ယောကျာ်းကို လေးစားသဖြင့်ရည်ညွှန်းသည်။ မိန်းမကိုလည်း ရည်ညွှန်းနိုင်သည်။)',NULL)
,(7927,3,16,'သင်။ အရှင်မ။ မိန်းမကို လေးစားသဖြင့်ရည်ညွှန်းသည်။','(ဂၞကျာ်ဇၞော်) ကဵုကော်နၚ်သမ္ဘာအမာတ်ဂမၠိုၚ်တုဲ “ယွံနာဲပိုဲဗြဴတံညးဂမၠိုၚ်၊ ပသာ်နာဲတံသ္ပရော” ဂၞကျာ်ဇၞော်ဂး။ (ဇ—၅ဝ၉။အစွောံ။) = မိဖုရားကြီးသည် အမတ်တို့၏မယားတို့ကို ခေါ်စေပြီးလျှင် “အိုအရှင်မတို့၊ သင်တို့အသို့ပြုကုန်အံ့နည်း” ဟုမိဖုရားကြီးမေး၏။')
,(7928,3,1,'တရားဆုံးဖြတ်သူ။ တရားသူကြီး။','“ဗောဓိသတ်ပိုဲ ဒှ်နာဲဗစာ သ္ဂုတ်သွာတ်သၞောဝ်ရောၚ်။” (ဇ—၃၃၂။ အစွောံ။) = “ဘုရားလောင်းသည် တရားဆုံးဖြစ်သော တရားသူကြီးဖြစ်၏။” || “အဲဒှ်အမာတ်နာဲဗ္စာ မပ္တုဲဒၟံၚ်သၞောဝ်ညးလၟိုန်ရောၚ်” ကၠဵုဂးကဵုဖေအ်ၜါ။ (ဇ—၄ဝဝ။ အစွောံ။) = “ငါသည် ရှေး­ တရားဆုံးဖြတ်သော အမတ်ကြီးသည်ဖြစ်ပြီ။” (ညောင်ကန်) || “နာဲအာဂစိုတ်ကၠေံကောန် (အဲ) တြ။ (အဲ) စိုတ်ဟွံဟဲ ညံၚ်တိုန်ဒုၚ်စဳရေၚ်နာဲဗစာရ” တၠကောန်ဂး။” (ဇ—၂၁၈။ အစွောံ။) = “ငါ့ကလေးကို သင်သတ်လိုက်ပြီ။ ငါမကျေနပ်၊ လာလှည့်၊ တရားသူကြီးထံ အစီအရင်ကို ခံယူကုန်အံ့” ဟုသားရှင်ဆို၏။ || “ကာလဗောဓိသတ်ပိုဲ ဒှ်မဟောသဓဂှ် ဗဗွဲဓဝ်ဟေၚ် မပနာဲဗစာညး။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “ဘုရားလောင်းသည် မဟော်သဓာဖြစ်သောကာလ­ တရားသဖြင့်သာလျှင် သူတစ်ပါးတို့၏ တရားသူကြီးအဖြစ် ဆောင်ရွက်၏။” || “နာဲပိုဲကဵုအဲပနာဲဗ္စာ ကဵုအဲစဳရေၚ်အမှုဂဗုတ်ဂလာန်ညး—။” (ဇ—၅၁၁။ အစွောံ။) = “ငါတို့အရှင်သည် ငါ့ကို တရားသူကြီးလုပ်စေ၍ သူတစ်ပါးတို့၏အမှုအခင်းကို စီရင်ဆုံးဖြတ်စေ၏။” || ‘သၟိၚ်ဗစာ’၊ ‘ဒကိုပ်ဗစာ’ ဟူ၍လည်းသုံးသည်။ || ‘ရုၚ်ဗစာ’ လည်းရှု။')
,(7929,3,1,'သခင်မ။ အရှင်မ။','“ယွံနာဲဗြဴ၊ မူရဴကိစ္စမွဲ နာဲဗြဴမကဵုအဲပ္တုဲကဵုရော” သၟာလှ်ေဍိက်ဂှ်ဂး။ (ဇ—၃၁၈။ အစွောံ။) = “သခင်မ၊ အကျွန်ုပ်ကို သခင်မသည် ဘာကိစ္စကို ဆောင်ရွက်စေလိုပါသနည်း” ဟုကျွန်ကချေသည်ဆို၏')
,(7929,3,2,'သင်။ (လေးစားသမှုဖြင့် မိန်းမကိုရည်ညွှန်းသောအသုံးအနှုန်းဖြစ်သည်။)','“တြုံဝွံ ပသာ်သဏောဝ်ကဵုနာဲဗြဴရော” ညးသၟာန်ဗြဴဂှ်ရ။ (ဇ—၁၉၃။အစွောံ။) = “ဤယောကျာ်းသည် သင်နှင့်အသို့တော်ကြသနည်း” ဟုလူတို့သည် ထိုမိန်းမကိုမေးကုန်၏။ || “မူဒၞာဲနာဲဗြဴမသ္အာရော” ညးသၟာန်ဍေံရ။ (ဇ—၂၈၅။ အစွောံ။) = “သင်ဘယ်သွားမည်နည်း” ဟုလူတို့သည် သူမကိုမေးကုန်၏။')
,(7930,3,1,'မျက်နှာလိုမျက်နှာရလုပ်သူ။',NULL)
,(7931,3,1,'တိုင်းပြည်၏အရှင်သခင်။ မင်း။ ဘုရင်။','“အီတဴဖျာဲဖျာဲ၊ ဝေၚ်ဒုၚ်ယာဲဇု။ သီုကဵုစရာဲ၊ကောန်သၟိၚ်နာဲမြု။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “တိုင်းပြည့်အရှင်သခင်မင်း၏သားတော်ဖြစ်သော အသရေနှင့်ပြည့်စုံသော မယ်မယ့်သားတော်သည် နှစ်နှစ်ခြိုက်ခြိုက်ပြုံးလျက် မယ်မယ့်ကို ခရီးဦးကြို၏။” || “ညံၚ်ထာၚ်ကဵုထိုက်၊ သ္ဍိုက်မၠိုက်သာဓာ။ ညံၚ်အိန်နာဲမြု၊ ကဵုသုဇာတာ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “ပွင့်ဖတ်ပွင့်ချပ်ချင်းကဲ့သို့၄င်း နတ်ပြည့်အရှင်သခင်သိကြားမင်းနှင့် သုဇာတာမိဖုရားတို့ကဲ့သို့၄င်း ချစ်ခင်ညီညွတ်ကြကုန်၏။” || “ကျာ်သဗ္ဗညု၊ နာဲမြုနိဗ္ဗာန်။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။) = “နိဗ္ဗာန်ပြည့်ရှင် သဗ္ဗညုဘုရား။”')
,(7932,3,1,'အဖွဲ့ခေါင်းဆောင်။ အဖွဲ့လူကြီး။','“ဆဏအ်တုဲ တန်ရမၞးတံ” နာဲရဲဂှ်ဟီု။ (ဇ—၄၉၃။အစွောံ။) = “အချင်းတို့၊ ဤမျှဖြင့်တန်ပါတော့” ဟု အဖွဲ့ခေါင်းဆောင်က တား၏။ || “မၞိဟ်တံဝွံ ဒိုအ်ရၜိုန်နာဲရဲဍေံ တြုံတၠပညာဂးကီုလေဝ် ဍေံဟွံဒိုအ်—။” (ဇ—၂၅၆။ အစွောံ) = “ဤလူတို့သည်ကား ရပ်ပါတော့ဟု သူတို့ခေါင်းဆောင်က ပြောဆိုသော်လည်း မရပ်ကုန်။” || “မဂဒူဟေၚ် ပနာဲရဲစၞးအပါဇကုပၠန်။” (အကြီုရာဇာဓိရာဇ်) = “မဂဒူးသည် ဖခင်ကိုယ်စား ကုန်သည်ခေါင်းဆောင်လုပ်ပြန်၏။”')
,(7933,3,1,'ရောင်ခြည်တော်ခြောက်သွယ်သခင်။ မြတ်စွာဘုရား။','“နာဲလျးတြဴ၊ စဴအာနဳဗာန်။” (လိက်လက္ခဏပိ) = “ရောင်ခြည်တော်ခြောက်သွယ်သခင် မြတ်စွာဘုရားသည် နိဗ္ဗာန်စံဝင်တော်မူသွား၏။” || “နာဲလျးတရဴ၊ ကျာ်သ္ဍဴဒိုဟ်စှ်။” (လိက်တပူတဗဝ်) = “ရောင်ခြည်တော် ခြောက်သွယ်ရှင် အရပ်ဆယ်မျက်နှာ၏မီးရှူးတန်ဆောင်ဖြစ်သော မြတ်စွာဘုရား။” || ‘တၠလျးတြဴ’နှင့်အတူတူ။')
,(7934,3,1,'အကြီးအကဲ။ အကြီးအမှူး။ ခေါင်းဆောင်။','နာဲသာဗၞိက် = ကုန်သည်ခေါင်းဆောင်။ကုန်သည်အကြီးအမှူး။ || နာဲသာလောက = လောက၏အကြီးအမှူး။ မြတ်စွာဘုရား။ || “ပ္ဍဲကာလဂှ် နာဲသာဗၞိက်သမၠီုဂှ်ကီုလေဝ် နကွဳမသုန်ကၠံ ပ္ဍိုက်ဗပေၚ်ဗၞိက်တုဲ သြပ်ဒၟံၚ်မသ္အာဗၞိက်ကီုရ။” (ဇ—၁။ အစွောံ။) = “ထိုအချိန်­ မိုက်သောကုန်သည်မှူးသည်လည်း လှည်းငါးရာတို့ဖြင့် ကုန်အ ပြည့်တင်ဆောင်၍ ကုန်အရောင်းအဝယ်သွားရန် အဆင်သင့်ဖြစ်နေ၏။” || “ဥပးမွဲဂှ် — စၚ်ကြံဒၟံၚ်ဒဵုတ္ၚဲယး ဇရေၚ်နာဲသာကွဳတံဂှ်ရ။” (ဇ—၄၁၄။ အစွောံ။) = “တစ်ယောက်သောသီတင်းသည်သည် လှည်းကုန်သည်မှူးတို့အနီး­ မိုးလင်းသည့်တိုင် စင်္ကြံသွား၍နေ၏။”')
,(7935,3,1,'လောက၏အကြီးအမှူး။ မြတ်စွာဘုရား။','“ကျာ်တြဲပိုဲရော၊ နာဲသာလောက။” (လိက်တပူတဗဝ်။ အစွောံ။) = “လောက၏အကြီးအမှူးဖြစ်သော ငါတို့မြတ်စွာဘုရား။” || “ကျာ်မဟာကရုဏာ နာဲသာလောကဓါတ် ဨကရာတ်နာဲညးဇမၞးဒိုဟ်စှ်—။” (ဇ—တေမဳ။ အစွောံ။) = “မဟာကရုဏာရှင်ဖြစ်တော်မူသော၊ လောက၏အကြီးအမှူးဖြစ်တော်မူသော၊ အရပ်ဆယ်မျက်နှာ အောင်သူတကာတို့၏ ဘုရင်ဖြစ်တော်မူသော မြတ်စွာဘုရား။”')
,(7936,3,1,'အရပ်ဆယ်မျက်နှာ၏ မီးရှူးတန်ဆောင်ဖြစ်သောသခင်။ မြတ်စွာဘုရား။','“ကျာ်လျးတြဴ၊ နာဲသ္ဍဴဒိုဟ်စှ်။” (လိက်တပူတဗဝ်။ အစွောံ။) = “ရောင်ခြည်တော်ခြောက်သွယ်ဖြင့် အရပ်ဆယ်မျက်နှာ၏ မီးရှူးတန်ဆောင်မြတ်စွာဘုရား။”')
,(7937,3,1,'လောက၏မီးရှူးတန်ဆောင်။ မြတ်စွာဘုရား။',NULL)
,(7938,3,1,'လူငယ်။',NULL)
,(7939,3,9,'—သော်။ —လေသော်။ —လတ်သော်။ —သည်ရှိသော်။','“တၠပညာတမၠာတေံကီုလေဝ် သမ္ဘာဇကုပကၠေံကာဂစိုတ်တုဲနေဝ် သဘဴမွဲမလေပ်လီုတုဲဂှ် ဍေံလီုရဂးတုဲ ညးဟွံဂွံစံၚ်တူရ” ကျာ်တြဲဂး။ (ဇ—၃၂၈။ အစွောံ။) = “ရှေးပညာရှိတို့သည်လည်း မယားသေလွန်သည်ရှိသော် ပျက်စီးတတ်သောသဘောသည် ပျက်စီး၏ဟု မစိုးရိမ်ကုန်။” (ညောင်ကန်) || “အ္စာတဳတံဂမၠိုၚ်ဂှ် နူကၠာကျာ်တြဲဟွံက္တဵုဒှ်ဏီဂှ် မၞုံကဵုလာဘသက္ကာရဂၠိုၚ် ဒှ်တဴရ။ ကျာ်တြဲက္တဵုဒှ်တုဲနေဝ်အ္စာတဳတံ မဒးဟုတ်အာနူလာဘသက္ကာရဂှ်ဒှ်တုဲ ညံၚ်ရဴကလဵုလိၚ်မအာပ်လျးတ္ၚဲကီု ဒယှ်တှ်အ္စာတဳတံပၠိုတ်အာအိုတ်ရ။” (ဇ—၃၃၉။ အစွောံ။) = “ထိုတိတ္ထိတို့သည် ဘုရားမဖြစ်မီ လာဘ်ရကုန်၏။ဘုရားဖြစ်တော်မူသည်ရှိသော်ကား ပျောက်သောလာဘသက္ကာရရှိကုန်သည်ဖြစ်၍ နေထွက်သောအခါ­ ပိုးစုန်းကြူးတို့ကဲ့သို့ဖြစ်ကုန်၏။” (ညောင်ကန်) || “ပ္ဍဲကာလဂိတုဇှ်ေဂှ် ဍာ်အောန် သတ်သြောံသ္ၚိတ်အာအိုတ်ဏေဝ် မၞိဟ်မကၠောန်သြောံတံဂှ် ကၠုၚ်ကောံတဴမွဲဟာန်အိုတ်ရ။” (ဇ—၅၃၆။အစွောံ။) = “နယုန်လအခါဝယ် ကောက်ပၚ်တို့သည် ညှိုးကုန်လတ်သော် နှစ်ပြည်သားတို့၏လယ်လုပ်သားတို့သည် စည်းဝေးကြကုန်၏။” (ညောင်ကန်)')
,(7940,3,4,'နှာချေဆေးဖြင့် နှာချေအောင်လုပ်သည်။','ဂဥုဲနုဟ် = နှာရှူဆေး။ || “ဂဥုဲရိုဟ်ဆု၊ ဝွံလေဝ်နွံကီု။ —— သ္ဂောံခရောတ်နုဟ်၊ ခအှ်ချီုချီု။” (လိက်သောဝါနနဟောၚ်) = “ဆေးမြစ်ရှိသည်ကို နှာရှူရသော် ဆက်တိုက်နှာချေ၏။”')
,(7941,3,1,'ကြံ့ချို။',NULL)
,(7942,3,4,'ရှိသည်။','“ပ္ဍဲအဲသြန်နွံမွဲကၠံရ။” = “ကျွန်တော့်မှာ ငွေတစ်ရာရှိသည်။” || “ကရပ်သ္ၚိတာဲဂှ် ကမၠိုၚ်နွံမွဲရ။” = “တဲအိမ်အနီးတွင် ရေတွင်းတစ်ခုရှိသည်။”')
,(7943,3,4,'ကျက်သရေရှိသည်။',NULL)
,(7944,3,4,'အကျိုးရှိသည်။',NULL)
,(7945,3,4,'တန်ဖိုးရှိသည်။ အဖိုးတန်သည်။',NULL)
,(7946,3,4,'မေတ္တာရှိသည်။ ချစ်ခင်သည်။',NULL)
,(7947,3,4,'အပြစ်ရှိသည်။',NULL)
,(7948,3,4,'ကရုဏာတရားရှိသည်။',NULL)
,(7949,3,4,'ခန္တီတရားရှိသည်။',NULL)
,(7950,3,4,'သည်းခံခြင်းတရားရှိသည်။ သည်းခံတတ်သည်။',NULL)
,(7951,3,4,'ပညာရှိသည်။',NULL)
,(7952,3,4,'မင်္ဂလာရှိသည်။',NULL)
,(7953,3,4,'ရုပ်ရည်ရှိသည်။ ရုပ်လှသည်။',NULL)
,(7954,3,4,'လုံ့လရှိသည်။ ဝီရိယရှိသည်။',NULL)
,(7955,3,1,'ကျောင်းထိုင်ဆရာတော်။','နွံပိုန်ဘာအစွောအ် = ဝေါဆရာတော်။')
,(7956,3,4,'“စိတ်ထဲတွင်ရှိသော်လည်း နှုတ်မှမထွက်လာ” ဟူသောအဓိပ္ပါယ်ရှိသည်။ (မိမိသေချာစွာသိထားသော သူတစ်ဦးတစ်ယောက်၏အမည်ကို စဉ်းစား၍မထွက်သောအခါမျိုး­သုံးလေ့ရှိသည်။)',NULL)
,(7957,3,4,'များစွာရှိသည်။ ပေါများသည်။','“(ယွံသၟိၚ်ကၞုဲ) ၊ ပ္ဍဲသြၚ်လ္ပာ်တေံဂှ် သတ်ကြုက်ကီုသတ်ဖါကီု နွံဗဝ်ဒၟံၚ်ရ။ ကၠောံအာဂၠာဲစဍေံမူဒှ်ရော” ကျာံဂး။ (ဇ—၂ဝ၈။ အစွောံ။) = “မျောက်မင်း၊ ထိုမှာဘက်ကမ်း­ သရက်သီး၊ တောင်ပိနနဲသီးတို့သည် အလွန်ပေါများကုန်၏။ သင်သည်သွား၍ရှာစားပါလား။”')
,(7958,3,4,'(ပြု) ရိုးရှိသည်။','‘သဘဴ’ တွင်ရှု။')
,(7959,3,4,'အမိန့်ရှိသည်။','“ယွံတၠညး၊ ပသာ်အသံနွံရောအဴ။” (ဇ—၃၅၈။ အစွောံ) = “မြတ်သောမင်းကြီး၊ အသို့အမိန့်တော်ရှိပါသနည်း။”')
,(7960,3,1,'ဖျာကြမ်း။','ဒကဝ်နှာ = စပါးလှန်းရာတွင်သုံးလေ့ရှိသောဖျာကြမ်း။')
,(7960,3,4,'လှော်သည်။','နှာမၜဲ = မြေပဲလှော်သည်။ || “ဆသ္ၚုမွဲတလတ် နှာဗဒှ်ဂၜိုဟ်တုဲ—။” (ဇ—၄၃ဝ။ အစွောံ။) = “ဆန်တစ်ပြည်မျှကို လှော်၍ထမင်းခြောက်လုပ်၏။”')
,(7961,3,4,'ဖိတ်သည်။','‘ဏှဳ’ ရှု။')
,(7962,3,4,'ယိုဖိတ်သည်။ ဆုံးရှုံးသည်။','‘ဏှဳချာဲ’ ရှု။')
,(7963,3,4,'သေသည်။','“ယးဟာကလဳ၊ တိုၚ်ဒးဏဳသ္ကန်။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “မနက်ဖြန်လား သန်ဘက်ခါလား သေရမည်သာဖြစ်သည်။” || ‘သ္ကန်နှဳ’ နှင့်အတူတူ။')
,(7964,3,4,'ရောသည်။ ရောနှောသည်။','“ယြဴပူဂဵုမွဲ မဒးနှဴကေုာံပူဂဵုသမၠီုဂှ် တသိုက်စိုတ်ကီုတသိုက်ကာယျကီု ဟွံကလိဂွံရ။” (ဇ—၂၇၂။ အစွောံ။) = “သူမိုက်နှင့်တကွ ရောနှောပေါင်းဖော်သောသူသည် စိတ်ချမ်းသာခြင်းကို၄င်း ကိုယ်ချမ်းသာခြင်းကို၄င်း မရ။” || “ကဵုဍေံမံၚ်ရ၊ ပကဵုသၞဴကၠာ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “မရောနှောစေဘဲ သူ့ကိုနေပါစေ။”')
,(7965,3,4,'ရောနှောသည်။ ချစ်ကျွမ်းဝင်သည်။','“နူဍောတ်နှဴဂၠိန်၊ ဆာန်ကၟိန်ထဒၟ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “ငယ်စဉ်ကတည်းက အတူနေထိုင်ရောယှက်၍ ချစ်ခင်လေးမြတ်ကြ၏။” || “ဂကောံဗြဴဂှ်စိ၊ ဗဒှ်သ္ၚိကၟိန်။ သၟဟ်သၟန်နှဴဂၠိန်၊ စိန်ဝုန်သာဓါ။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “ထိုမိန်းမနှင့် အိမ်ထောင်ပြု၍ ညီညွတ်ချစ်ကျွမ်းဝင်ကာ မွေ့လျော်ပျော်ရွှင်၏။” || ‘ဂၠိန်နှဴ’နှင့်အတူတူ။')
,(7966,3,1,'(ပါးစပ်တွင်းရှိ) အာစောက်။',NULL)
,(7967,3,4,'ရောနှောသည်။ ရောယှက်သည်။','“ပုၚ်နှဴရဴဒၟံၚ်ကဵုသကာမ်ဂှ် ညးဗစကၠိက်ရ။” = “ဖွဲနှင့်ရောနေသောထမင်းကို ဝက်စာကျွေး၏။” || “ပွနှဴရဴကေုာံသမၠီု ဟွံဂပ်ဂဝ်ကွေံရ။” (ဇ—၁၄၁။ အစွောံ။) = “သူမိုက်နှင့်တကွ ရောနှောခြင်းသည် စင်စစ်မသင့်လျော်။” || “ပွမနှဴရဴမဒၟံၚ် မွဲဟာန်ကေုာံကမၠတ်ဂှ် ဟွံဂပ်ဂဝ်သွံ။” (ဇ—၃၁၁။ အစွောံ။) = “ခိုးသူနှင့်တကွ ရောနှော ခြင်းမည်သည်ကား မအပ်။” (ညောင်ကန်) || “ကာလဗမၞးမသတိတ်အာနူသ္ၚိဂှ် ကေုာံတြုံသ္ကဲဗမၞိဟ်ဂှ် နှဴရဴတဴရ။” (ဇ—၁၃ဝ။ အစွောံ။) = “ပုဏ္ဏားအိမ်မှထွက်သွားသောအခါ လၚ်မြှောင်နှင့်တကွပုဏ္ဏေးမသည် ရောယှက်ဆက်ဆံ၏။” || “အမာတ်သၟိၚ်ကောသလရးမွဲဂှ် ပ္ဍဲဗြဴကမၠောန်ပ္ဍဲသ္ၚိသၟိၚ်ဂှ်အမာတ်ဒဒှ်ေယှ်ဏှဴရဴအာရ။” (ဇ—၁၉၅။ အစွောံ။) = “ကောသလမင်း၏တစ်ယောက်သောအမတ်သည် နန်းတွင်းသူတစ်ယောက်နှင့် အကျွမ်းဝင်လွန်ကျူးရောယှက်၏။” || “ပကဵုသၞဴရဴ၊ မံၚ်တဴသေၚ်ဟာ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “မရောယှက်စေဘဲ နေသည်မဟုတ်လော။”')
,(7968,3,1,'ငါးဖမ်းသည့်ကြမ်းတိုက်ပိုက်။',NULL)
